const TEORIA = {
  "1": "<section class=\"mb-5\" id=\"ddl-section\">\n<h2 class=\"display-5 fw-bold text-primary mb-4 border-bottom pb-2\">1. DDL: Definición de Datos\n                        </h2>\n<!-- 1.1 Create DB & Tables -->\n<article class=\"card bg-glass border-0 shadow-sm p-4 mb-4\" id=\"ddl-create\">\n<h3 class=\"text-white\"><i class=\"fas fa-plus-circle me-2 text-success\"></i>1.1 Creación de\n                                Base de Datos y Tablas</h3>\n<p>El DDL (Data Definition Language) nos permite crear la estructura donde se almacenarán\n                                nuestros datos. Piensa en esto como construir los cimientos y las paredes de una casa\n                                antes de poner los muebles (datos).</p>\n<h5 class=\"mt-4 text-info\">Concepto Clave: Tipos de Datos</h5>\n<p class=\"small text-muted\">Es vital elegir el tipo de dato correcto para optimizar el\n                                espacio y asegurar la integridad.</p>\n<ul class=\"text-light small\">\n<li><code>INT</code>: Números enteros (IDs, cantidades, edades).</li>\n<li><code>DECIMAL(10,2)</code>: Dinero o medidas exactas. (10 dígitos en total, 2\n                                    decimales).</li>\n<li><code>VARCHAR(n)</code>: Texto variable hasta 'n' caracteres (Nombres, emails).</li>\n<li><code>TEXT</code>: Texto largo sin límite predefinido corto (Descripciones).</li>\n<li><code>BOOLEAN</code>: Verdadero (TRUE/1) o Falso (FALSE/0).</li>\n<li><code>TIMESTAMP / DATETIME</code>: Fechas y horas.</li>\n</ul>\n<h5 class=\"mt-4 text-info\">Creación (Código Real)</h5>\n<div class=\"code-block-wrapper\">\n<pre><code class=\"language-sql\">-- 1. Crear el contenedor (Base de Datos)\nCREATE DATABASE IF NOT EXISTS arepazo;\nUSE arepazo;\n\n-- 2. Crear una Tabla simple\nCREATE TABLE Platos (\n    plato_id INT AUTO_INCREMENT PRIMARY KEY, -- Identificador único auto-generado\n    nombre_plato VARCHAR(100) NOT NULL UNIQUE, -- Obligatorio y no repetido\n    precio_venta DECIMAL(10, 2) NOT NULL,\n    disponible BOOLEAN DEFAULT TRUE -- Si no se especifica, será Verdadero\n);</code></pre>\n</div>\n<h5 class=\"mt-4 text-info\"><i class=\"fas fa-dumbbell me-2\"></i>Ejercicios de Creación (1-10)\n                            </h5>\n<div class=\"accordion accordion-flush bg-transparent\" id=\"accordionDDL\">\n<!-- Ej 1 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-ddl-1\" data-bs-toggle=\"collapse\" type=\"button\">1. Tabla\n                                            de Usuarios Básica</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDDL\" id=\"ex-ddl-1\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Escribe la sentencia SQL para crear una tabla\n                                                llamada <code>Usuarios</code>. Debe tener un identificador único, un\n                                                nombre de usuario obligatorio y una contraseña.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: General /\n                                                    Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">CREATE TABLE Usuarios (\n    id INT AUTO_INCREMENT PRIMARY KEY,\n    username VARCHAR(50) NOT NULL,\n    password VARCHAR(100)\n);</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ej 2 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-ddl-2\" data-bs-toggle=\"collapse\" type=\"button\">2. Tabla\n                                            de Libros (Biblioteca)</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDDL\" id=\"ex-ddl-2\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Diseña una tabla para una\n                                                <code>Biblioteca</code>. La tabla <code>Libros</code> debe usar el ISBN\n                                                como clave primaria (texto 13 chars), y almacenar título, autor y número\n                                                de páginas.<br/>\n<span class=\"badge bg-secondary mb-2\">Contexto: Biblioteca\n                                                    (Nueva)</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">CREATE TABLE Libros (\n    isbn VARCHAR(13) PRIMARY KEY,\n    titulo VARCHAR(200) NOT NULL,\n    autor VARCHAR(100),\n    paginas INT\n);</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ej 3 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-ddl-3\" data-bs-toggle=\"collapse\" type=\"button\">3. Tabla\n                                            de Empleados con Fechas</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDDL\" id=\"ex-ddl-3\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Crea una tabla <code>Empleados</code> que\n                                                registre el nombre, la fecha exacta de nacimiento y su salario con\n                                                precisión de centavos.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">CREATE TABLE Empleados (\n    id INT AUTO_INCREMENT PRIMARY KEY,\n    nombre VARCHAR(100),\n    fecha_nacimiento DATE,\n    salario DECIMAL(10,2)\n);</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ej 4 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-ddl-4\" data-bs-toggle=\"collapse\" type=\"button\">4.\n                                            Restricción UNIQUE</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDDL\" id=\"ex-ddl-4\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Necesitamos una lista de <code>Paises</code>.\n                                                Asegúrate de que no se puedan insertar dos países con el mismo nombre\n                                                usando una restricción.<br/>\n<span class=\"badge bg-secondary mb-2\">Contexto: Geografía</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">CREATE TABLE Paises (\n    id INT PRIMARY KEY,\n    nombre_pais VARCHAR(100) UNIQUE\n);</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ej 5 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-ddl-5\" data-bs-toggle=\"collapse\" type=\"button\">5. Valor\n                                            por Defecto (DEFAULT)</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDDL\" id=\"ex-ddl-5\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Crea una tabla <code>Tareas</code> donde el\n                                                campo 'estado' se rellene automáticamente con el valor 'Pendiente' si el\n                                                usuario no especifica nada.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: General</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">CREATE TABLE Tareas (\n    id INT AUTO_INCREMENT PRIMARY KEY,\n    descripcion TEXT,\n    estado VARCHAR(20) DEFAULT 'Pendiente'\n);</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ej 6 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-ddl-6\" data-bs-toggle=\"collapse\" type=\"button\">6. Clave\n                                            Primaria Compuesta</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDDL\" id=\"ex-ddl-6\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Crea la tabla intermedia\n                                                <code>Matriculas</code>. Un alumno puede estar en varios cursos, y un\n                                                curso tiene varios alumnos. La clave primaria debe ser la combinación de\n                                                ambos IDs.<br/>\n<span class=\"badge bg-secondary mb-2\">Contexto: Educación</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">CREATE TABLE Matriculas (\n    alumno_id INT,\n    curso_id INT,\n    año INT,\n    PRIMARY KEY (alumno_id, curso_id)\n);</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ej 7 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-ddl-7\" data-bs-toggle=\"collapse\" type=\"button\">7. Crear\n                                            Tabla desde Select (Backup)</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDDL\" id=\"ex-ddl-7\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> (Avanzado) Crea una nueva tabla\n                                                `Usuarios_Backup` y llénala automáticamente con todos los datos que ya\n                                                existen en la tabla `Usuarios`.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">CREATE TABLE Usuarios_Backup AS SELECT * FROM Usuarios;</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ej 8 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-ddl-8\" data-bs-toggle=\"collapse\" type=\"button\">8. Tabla\n                                            con Foreign Key (Categoria)</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDDL\" id=\"ex-ddl-8\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Crea una tabla <code>Productos</code> que\n                                                tenga una referencia (Foreign Key) a la tabla <code>Categoria</code>\n                                                (campo id). Esto asegura integridad referencial.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">CREATE TABLE Productos (\n    id INT PRIMARY KEY,\n    nombre VARCHAR(50),\n    cat_id INT,\n    FOREIGN KEY (cat_id) REFERENCES Categoria(id)\n);</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ej 9 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-ddl-9\" data-bs-toggle=\"collapse\" type=\"button\">9. Tabla\n                                            Temporal (Memory)</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDDL\" id=\"ex-ddl-9\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Crea una tabla temporal <code>Calculos</code>\n                                                que solo exista durante tu sesión actual. Útil para almacenar resultados\n                                                intermedios.<br/>\n<span class=\"badge bg-secondary mb-2\">Contexto: Sesión / Scripts</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">CREATE TEMPORARY TABLE Calculos (\n    resultado DECIMAL(10,2)\n);</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ej 10 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-ddl-10\" data-bs-toggle=\"collapse\" type=\"button\">10.\n                                            Tabla con Check (Validación)</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDDL\" id=\"ex-ddl-10\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Crea una tabla <code>Personas</code> con una\n                                                restricción CHECK que impida insertar registros si la edad es menor de\n                                                18 años.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: General</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">CREATE TABLE Personas (\n    nombre VARCHAR(50),\n    edad INT CHECK (edad &gt;= 18)\n);</pre>\n</details>\n</div>\n</div>\n</div>\n</div>\n</article>\n<!-- 1.2 Modify Tables -->\n<article class=\"card bg-glass border-0 shadow-sm p-4 mb-4\" id=\"ddl-modify\">\n<h3 class=\"text-white\"><i class=\"fas fa-edit me-2 text-warning\"></i>1.2 Modificación de\n                                Tablas (ALTER)</h3>\n<p>Las tablas no son estáticas. A menudo los requisitos cambian y necesitamos adaptarlas.\n                            </p>\n<pre><code class=\"language-sql\">-- 1. Añadir columna nueva\nALTER TABLE Usuarios ADD COLUMN email VARCHAR(100);\n\n-- 2. Modificar el tipo de dato (¡Cuidado si hay datos!)\nALTER TABLE Usuarios MODIFY COLUMN username VARCHAR(150);\n\n-- 3. Renombrar columna\nALTER TABLE Usuarios CHANGE COLUMN password pass_hash VARCHAR(255);\n\n-- 4. Borrar columna\nALTER TABLE Usuarios DROP COLUMN fecha_nacimiento;</code></pre>\n<h5 class=\"mt-4 text-info\"><i class=\"fas fa-dumbbell me-2\"></i>Ejercicios de Modificación\n                                (1-5)</h5>\n<div class=\"accordion accordion-flush bg-transparent\" id=\"accordionDDL-Mod\">\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-ddl-m1\" data-bs-toggle=\"collapse\" type=\"button\">1.\n                                            Añadir Teléfono</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDDL-Mod\" id=\"ex-ddl-m1\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Modifica la tabla <code>Clientes</code> para\n                                                añadir una nueva columna llamada <code>telefono</code> que pueda\n                                                almacenar hasta 15 caracteres.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">ALTER TABLE Clientes ADD COLUMN telefono VARCHAR(15);</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-ddl-m2\" data-bs-toggle=\"collapse\" type=\"button\">2. Hacer\n                                            campo obligatorio</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDDL-Mod\" id=\"ex-ddl-m2\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Cambia la columna <code>email</code> de la\n                                                tabla <code>Usuarios</code> para que no acepte valores nulos (NOT\n                                                NULL).<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: General</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">ALTER TABLE Usuarios MODIFY COLUMN email VARCHAR(100) NOT NULL;</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-ddl-m3\" data-bs-toggle=\"collapse\" type=\"button\">3.\n                                            Añadir Clave Primaria a tabla existente</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDDL-Mod\" id=\"ex-ddl-m3\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Tienes una tabla llamada <code>MiTabla</code>\n                                                que se creó sin clave primaria. Modifícala para que la columna\n                                                <code>id</code> sea la PRIMARY KEY.<br/>\n<span class=\"badge bg-secondary mb-2\">Contexto: General</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">ALTER TABLE MiTabla ADD PRIMARY KEY (id);</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-ddl-m4\" data-bs-toggle=\"collapse\" type=\"button\">4.\n                                            Añadir valor por defecto</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDDL-Mod\" id=\"ex-ddl-m4\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Define un valor por defecto (1) para la\n                                                columna <code>activo</code> en la tabla <code>Usuarios</code>.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: General</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">ALTER TABLE Usuarios ALTER COLUMN activo SET DEFAULT 1;</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-ddl-m5\" data-bs-toggle=\"collapse\" type=\"button\">5.\n                                            Borrar la FK</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDDL-Mod\" id=\"ex-ddl-m5\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Elimina la restricción de clave foránea\n                                                llamada <code>fk_categoria</code> de la tabla\n                                                <code>Productos</code>.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">ALTER TABLE Productos DROP FOREIGN KEY fk_categoria;</pre>\n</details>\n</div>\n</div>\n</div>\n</div>\n</article>\n<!-- 1.3 Drop Tables -->\n<article class=\"card bg-glass border-0 shadow-sm p-4 mb-4\" id=\"ddl-drop\">\n<h3 class=\"text-white\"><i class=\"fas fa-trash me-2 text-danger\"></i>1.3 Borrado (Drop)</h3>\n<p class=\"text-danger\">Esta operación destruye la estructura y los datos permanentemente.\n                            </p>\n<pre><code class=\"language-sql\">DROP TABLE IF EXISTS Clientes;\nDROP DATABASE IF EXISTS arepazo_test;</code></pre>\n<div class=\"alert alert-warning mt-2\"><i class=\"fas fa-exclamation-triangle\"></i> ¡TRUNCATE\n                                vs DROP! <br/> <code>TRUNCATE TABLE</code> borra los datos pero deja la tabla vacía.\n                                <code>DROP</code> borra todo.\n                            </div>\n</article>\n</section>",
  "2": "<article class=\"card bg-glass border-0 shadow-sm p-4 mb-4\" id=\"dml-select\">\n<h3 class=\"text-white\"><i class=\"fas fa-search me-2 text-info\"></i>2.1 Consultas Básicas\n                                    (SELECT, WHERE)</h3>\n<h5 class=\"text-info\">Concepto: Orden de Ejecución</h5>\n<p>Aunque escribimos <code>SELECT ... FROM ... WHERE</code>, el motor de base de datos\n                                    lo procesa en este orden: <strong>FROM -&gt; WHERE -&gt; SELECT</strong>.</p>\n<!-- Animation: SELECT (Projection) -->\n<div class=\"card bg-dark border-info mb-4 overflow-hidden\" id=\"select-sim-container\">\n<div class=\"card-header bg-info bg-opacity-10 border-bottom border-info d-flex justify-content-between align-items-center\">\n<h5 class=\"mb-0 text-white\"><i class=\"fas fa-columns me-2 text-info\"></i>Simulación 1: SELECT (Que\n                                            columnas veo)</h5>\n<div class=\"code-badge bg-black border border-info rounded px-3 py-1 font-monospace text-info small shadow-sm\" id=\"select-query-display\">\n                                            SELECT * FROM Productos\n                                        </div>\n</div>\n<div class=\"card-body p-4\">\n<div class=\"d-flex justify-content-center gap-3 mb-4\">\n<button class=\"btn btn-sm btn-outline-light\" onclick=\"runSelectSim('ALL')\">SELECT * (Todo)</button>\n<button class=\"btn btn-sm btn-outline-light\" onclick=\"runSelectSim('SPECIFIC')\">SELECT nombre, precio</button>\n</div>\n<div class=\"table-responsive\">\n<table class=\"table table-dark table-sm table-bordered mb-0\" id=\"select-sim-table\">\n<thead>\n<tr>\n<th class=\"col-id\">id</th>\n<th class=\"col-name text-info\">nombre</th>\n<th class=\"col-cat\">categoria</th>\n<th class=\"col-price text-info\">precio</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td>Arepa</td>\n<td>Comida</td>\n<td>5.00</td>\n</tr>\n<tr>\n<td>2</td>\n<td>Jugo</td>\n<td>Bebida</td>\n<td>2.00</td>\n</tr>\n<tr>\n<td>3</td>\n<td>Café</td>\n<td>Bebida</td>\n<td>1.50</td>\n</tr>\n</tbody>\n</table>\n</div>\n<div class=\"small text-muted mt-2 text-center\" id=\"select-feedback\">\n                                            El asterisco (*) trae TODAS las columnas.\n                                        </div>\n</div>\n</div>\n<!-- Animation: WHERE (Filtering) -->\n<div class=\"card bg-dark border-warning mb-4 overflow-hidden\" id=\"where-sim-container\">\n<div class=\"card-header bg-warning bg-opacity-10 border-bottom border-warning d-flex justify-content-between align-items-center\">\n<h5 class=\"mb-0 text-white\"><i class=\"fas fa-filter me-2 text-warning\"></i>Simulación 2: WHERE (Que\n                                            filas veo)</h5>\n<div class=\"code-badge bg-black border border-warning rounded px-3 py-1 font-monospace text-warning small shadow-sm\" id=\"where-query-display\">\n                                            SELECT * FROM Productos\n                                        </div>\n</div>\n<div class=\"card-body p-4\">\n<div class=\"d-flex flex-wrap justify-content-center gap-2 mb-4\">\n<button class=\"btn btn-sm btn-outline-light\" onclick=\"runWhereSim('NONE')\">Sin Filtro</button>\n<button class=\"btn btn-sm btn-outline-light\" onclick=\"runWhereSim('PRICE')\">precio &lt; 3</button>\n<button class=\"btn btn-sm btn-outline-light\" onclick=\"runWhereSim('AND')\">cat='Bebida' AND precio &lt;\n                                                            2</button>\n<button class=\"btn btn-sm btn-outline-light\" onclick=\"runWhereSim('OR')\">cat='Comida' OR precio &lt;\n                                                                    2</button>\n</div>\n<div class=\"table-responsive\">\n<table class=\"table table-dark table-sm table-bordered mb-0\" id=\"where-sim-table\">\n<thead>\n<tr>\n<th>id</th>\n<th>nombre</th>\n<th>categoria</th>\n<th>precio</th>\n</tr>\n</thead>\n<tbody>\n<tr data-cat=\"Comida\" data-price=\"5.00\">\n<td>1</td>\n<td>Arepa</td>\n<td>Comida</td>\n<td>5.00</td>\n</tr>\n<tr data-cat=\"Bebida\" data-price=\"2.00\">\n<td>2</td>\n<td>Jugo</td>\n<td>Bebida</td>\n<td>2.00</td>\n</tr>\n<tr data-cat=\"Bebida\" data-price=\"1.50\">\n<td>3</td>\n<td>Café</td>\n<td>Bebida</td>\n<td>1.50</td>\n</tr>\n<tr data-cat=\"Postre\" data-price=\"3.50\">\n<td>4</td>\n<td>Torta</td>\n<td>Postre</td>\n<td>3.50</td>\n</tr>\n</tbody>\n</table>\n</div>\n<div class=\"small text-muted mt-2 text-center\" id=\"where-feedback\">\n                                            Mostrando todos los registros.\n                                        </div>\n</div>\n</div>\n<div class=\"row mt-4\">\n<div class=\"col-md-6\">\n<h6>Selección Simple</h6>\n<pre><code class=\"language-sql\">SELECT * FROM Platos;</code></pre>\n</div>\n<div class=\"col-md-6\">\n<h6>Proyección (Columnas específicas)</h6>\n<pre><code class=\"language-sql\">SELECT nombre_plato, precio_venta \nFROM Platos;</code></pre>\n</div>\n</div>\n<h5 class=\"mt-3 text-info\">Filtrado Avanzado (WHERE)</h5>\n<pre><code class=\"language-sql\">-- Rango de valores (BETWEEN)\nSELECT * FROM Platos WHERE precio_venta BETWEEN 5 AND 10;\n\n-- Lista de valores (IN)\nSELECT * FROM Platos WHERE categoria IN ('Arepas', 'Bebidas');\n\n-- Patrones de texto (LIKE)\n-- % = cualquier cadena, _ = un carácter\nSELECT * FROM Clientes WHERE email LIKE '%@gmail.com';\n\n-- Combinando condiciones (AND / OR / Parentesis)\nSELECT * FROM Pedidos \nWHERE (estado = 'Pagado' AND total_pedido &gt; 20) \n   OR (tipo_pedido = 'Delivery');</code></pre>\n<!-- Exercise DML 1 -->\n<h5 class=\"mt-4 text-info\"><i class=\"fas fa-dumbbell me-2\"></i>Ejercicios de Consultas\n                                    (1-10)</h5>\n<div class=\"accordion accordion-flush bg-transparent\" id=\"accordionDML-Select\">\n<!-- Ex 1 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-sel-1\" data-bs-toggle=\"collapse\" type=\"button\">1.\n                                                Arepas Baratas</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Select\" id=\"ex-sel-1\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Queremos encontrar las ofertas. Muestra\n                                                    el nombre y precio de los platos de la categoría 'Arepas' que\n                                                    cuesten menos de 7.00.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT nombre_plato, precio_venta \nFROM Platos \nWHERE categoria = 'Arepas' AND precio_venta &lt; 7.00;</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ex 2 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-sel-2\" data-bs-toggle=\"collapse\" type=\"button\">2.\n                                                Clientes 'Ana' o 'Juan'</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Select\" id=\"ex-sel-2\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Busca en la tabla Clientes a las personas\n                                                    que se llamen exactamente 'Ana' o 'Juan'.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT * FROM Clientes WHERE nombre IN ('Ana', 'Juan');</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ex 3 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-sel-3\" data-bs-toggle=\"collapse\" type=\"button\">3.\n                                                Búsqueda por Apellido</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Select\" id=\"ex-sel-3\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Encuentra todos los clientes cuyos\n                                                    apellidos comiencen por la letra 'G'.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT * FROM Clientes WHERE apellido LIKE 'G%';</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ex 4 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-sel-4\" data-bs-toggle=\"collapse\" type=\"button\">4.\n                                                Pedidos Recientes</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Select\" id=\"ex-sel-4\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Filtra la tabla de Pedidos para mostrar\n                                                    solo aquellos realizados después del 5 de Octubre de 2025.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT * FROM Pedidos WHERE fecha_hora &gt; '2025-10-05';</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ex 5 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-sel-5\" data-bs-toggle=\"collapse\" type=\"button\">5.\n                                                Rango de Precios</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Select\" id=\"ex-sel-5\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Muestra los platos cuyo precio esté\n                                                    comprendido entre 5 y 8 euros (inclusive).<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT * FROM Platos WHERE precio_venta BETWEEN 5 AND 8;</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ex 6 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-sel-6\" data-bs-toggle=\"collapse\" type=\"button\">6.\n                                                Oferta Especial (AND Compuesto)</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Select\" id=\"ex-sel-6\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Busca platos que sean 'Entrantes' O\n                                                    'Postres', pero ADEMÁS deben costar menos de 4.00.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT * FROM Platos \nWHERE (categoria = 'Entrantes' OR categoria = 'Postres') \nAND precio_venta &lt; 4.00;</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ex 7 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-sel-7\" data-bs-toggle=\"collapse\" type=\"button\">7. No\n                                                Disponibles</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Select\" id=\"ex-sel-7\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Muestra la lista de platos que\n                                                    actualmente NO están disponibles para la venta.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT * FROM Platos WHERE disponible = FALSE;</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ex 8 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-sel-8\" data-bs-toggle=\"collapse\" type=\"button\">8.\n                                                Ordenar por Precio</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Select\" id=\"ex-sel-8\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Queremos ver la carta ordenada por\n                                                    precio, mostrando primero los platos más caros.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT * FROM Platos ORDER BY precio_venta DESC;</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ex 9 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-sel-9\" data-bs-toggle=\"collapse\" type=\"button\">9.\n                                                Top 3 Más Caros</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Select\" id=\"ex-sel-9\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Obtén solamente los 3 platos con el\n                                                    precio de venta más alto.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT * FROM Platos ORDER BY precio_venta DESC LIMIT 3;</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ex 10 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-sel-10\" data-bs-toggle=\"collapse\" type=\"button\">10.\n                                                Distintas Categorías</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Select\" id=\"ex-sel-10\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Queremos saber qué tipos de categorías\n                                                    existen en nuestra tabla de Platos, sin ver duplicados.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT DISTINCT categoria FROM Platos;</pre>\n</details>\n</div>\n</div>\n</div>\n</div>\n</article><article class=\"card bg-glass border-0 shadow-sm p-4 mb-4\" id=\"dml-orderby\">\n<h4 class=\"text-white\"><i class=\"fas fa-sort-amount-down me-2 text-success\"></i>2.1a\n                                    Ordenamiento (ORDER BY)</h4>\n<p>Por defecto, el orden de los datos no está garantizado. Si quieres un orden\n                                    específico, ¡pídelo!</p>\n<div class=\"row mb-4\">\n<div class=\"col-md-6\">\n<div class=\"p-3 bg-dark border border-secondary rounded h-100\">\n<h6 class=\"text-info\">ASC (Ascendente)</h6>\n<p class=\"small text-muted\">De menor a mayor (A-Z, 0-9). Es el valor por\n                                                defecto.</p>\n<pre class=\"mb-0\"><code class=\"language-sql\">ORDER BY precio ASC</code></pre>\n</div>\n</div>\n<div class=\"col-md-6\">\n<div class=\"p-3 bg-dark border border-secondary rounded h-100\">\n<h6 class=\"text-warning\">DESC (Descendente)</h6>\n<p class=\"small text-muted\">De mayor a menor (Z-A, 9-0).</p>\n<pre class=\"mb-0\"><code class=\"language-sql\">ORDER BY precio DESC</code></pre>\n</div>\n</div>\n</div>\n<!-- Animation: ORDER BY -->\n<div class=\"card bg-dark border-success mb-4 overflow-hidden\" id=\"orderby-sim-container\">\n<div class=\"card-header bg-success bg-opacity-10 border-bottom border-success d-flex justify-content-between align-items-center\">\n<h5 class=\"mb-0 text-white\"><i class=\"fas fa-sort me-2 text-success\"></i>Simulación: Ordenando Datos\n                                        </h5>\n<div class=\"code-badge bg-black border border-success rounded px-3 py-1 font-monospace text-success small shadow-sm\" id=\"orderby-query-display\">\n                                            SELECT * FROM Productos ORDER BY ...\n                                        </div>\n</div>\n<div class=\"card-body p-4\">\n<div class=\"d-flex justify-content-center gap-3 mb-4\">\n<button class=\"btn btn-sm btn-outline-light\" onclick=\"runOrderBySim('ASC')\">\n<i class=\"fas fa-sort-amount-down-alt me-1\"></i> Precio ASC (Barato a\n                                                Caro)\n                                            </button>\n<button class=\"btn btn-sm btn-outline-light\" onclick=\"runOrderBySim('DESC')\">\n<i class=\"fas fa-sort-amount-down me-1\"></i> Precio DESC (Caro a Barato)\n                                            </button>\n</div>\n<div class=\"table-responsive\" style=\"max-width: 400px; margin: 0 auto;\">\n<table class=\"table table-dark table-sm table-bordered mb-0 text-center\" id=\"orderby-sim-table\">\n<thead>\n<tr>\n<th>Producto</th>\n<th class=\"text-warning\">Precio</th>\n</tr>\n</thead>\n<tbody class=\"position-relative\">\n<!-- Filled by JS -->\n</tbody>\n</table>\n</div>\n<div class=\"small text-muted mt-3 text-center\" id=\"orderby-feedback\">\n                                            Selecciona un orden para ver la magia.\n                                        </div>\n</div>\n</div>\n</article><article class=\"card bg-glass border-0 shadow-sm p-4 mb-4\" id=\"dml-manipulation\">\n<h4 class=\"text-white\"><i class=\"fas fa-magic me-2 text-warning\"></i>2.1.b Manipulación\n                                    de Datos (Funciones)</h4>\n<p>En el mismo <code>SELECT</code> puedes transformar los datos \"al vuelo\" usando\n                                    funciones.</p>\n<h5 class=\"mt-4 text-info\">Texto (Strings)</h5>\n<pre><code class=\"language-sql\">-- Concatenar (Unir texto)\nSELECT CONCAT(nombre, ' ', apellido) as Nombre_Completo FROM Clientes;\n\n-- Mayúsculas / Minúsculas\nSELECT UPPER(nombre_plato) FROM Platos;\n\n-- Longitud y Recorte\nSELECT SUBSTRING(descripcion, 1, 20) as Inicio_Desc, LENGTH(email) as Largo \nFROM Platos;</code></pre>\n<h5 class=\"mt-4 text-info\">Números y Matemática</h5>\n<pre><code class=\"language-sql\">-- Operaciones Aritméticas (+, -, *, /)\nSELECT nombre_plato, (precio_venta * 1.21) as Precio_con_IVA \nFROM Platos;\n\n-- Redondeo\nSELECT ROUND(precio_kg * 4.567, 2) as Coste_Calc FROM Ingredientes;</code></pre>\n<!-- Simulation: String Machine -->\n<div class=\"card bg-dark border-info mb-4 overflow-hidden\" id=\"string-sim-container\">\n<div class=\"card-header bg-info bg-opacity-10 border-bottom border-info text-white\">\n<h5 class=\"mb-0\"><i class=\"fas fa-font me-2 text-info\"></i>Simulación: Funciones\n                                            de Texto</h5>\n</div>\n<div class=\"card-body p-4 text-center\">\n<h6 class=\"text-secondary mb-3\">Valor Original (Columna 'Nombre')</h6>\n<div class=\"display-5 text-white fw-bold mb-4\" id=\"str-input\">LeBron James</div>\n<div class=\"d-flex flex-wrap justify-content-center gap-2 mb-4\">\n<button class=\"btn btn-outline-info\" onclick=\"runStrFunc('UPPER')\">UPPER()</button>\n<button class=\"btn btn-outline-info\" onclick=\"runStrFunc('LOWER')\">LOWER()</button>\n<button class=\"btn btn-outline-info\" onclick=\"runStrFunc('LENGTH')\">LENGTH()</button>\n<button class=\"btn btn-outline-info\" onclick=\"runStrFunc('REVERSE')\">REVERSE()</button>\n<button class=\"btn btn-outline-info\" onclick=\"runStrFunc('LEFT')\">LEFT(x,\n                                                3)</button>\n<button class=\"btn btn-outline-info\" onclick=\"runStrFunc('RIGHT')\">RIGHT(x,\n                                                3)</button>\n<button class=\"btn btn-outline-info\" onclick=\"runStrFunc('SUBSTRING')\">SUBSTRING(x, 1, 3)</button>\n<button class=\"btn btn-outline-info\" onclick=\"runStrFunc('REPLACE')\">REPLACE('e', 'X')</button>\n<button class=\"btn btn-outline-warning\" onclick=\"resetStrFunc()\">Reset</button>\n</div>\n<div class=\"card bg-black border-secondary p-3 position-relative\">\n<small class=\"text-muted d-block text-start font-monospace mb-2\">RESULTADO\n                                                SQL:</small>\n<div class=\"font-monospace text-info fs-4\" id=\"str-output\">LeBron James\n                                            </div>\n<div class=\"text-muted small mt-2\" id=\"str-query-display\">SELECT nombre FROM\n                                                Jugadores;</div>\n</div>\n</div>\n</div>\n<!-- Simulation: Number Machine -->\n<div class=\"card bg-dark border-success mb-4 overflow-hidden\" id=\"num-sim-container\">\n<div class=\"card-header bg-success bg-opacity-10 border-bottom border-success text-white\">\n<h5 class=\"mb-0\"><i class=\"fas fa-calculator me-2 text-success\"></i>Simulación:\n                                            Funciones Numéricas</h5>\n</div>\n<div class=\"card-body p-4 text-center\">\n<h6 class=\"text-secondary mb-3\">Valor Original (Columna 'Precio')</h6>\n<div class=\"display-5 text-white fw-bold mb-4\" id=\"num-input\">15.6789</div>\n<div class=\"d-flex flex-wrap justify-content-center gap-2 mb-4\">\n<button class=\"btn btn-outline-success\" onclick=\"runNumFunc('ROUND')\">ROUND(x, 2)</button>\n<button class=\"btn btn-outline-success\" onclick=\"runNumFunc('FLOOR')\">FLOOR()</button>\n<button class=\"btn btn-outline-success\" onclick=\"runNumFunc('CEIL')\">CEIL()</button>\n<button class=\"btn btn-outline-success\" onclick=\"runNumFunc('MOD')\">MOD(x,\n                                                2)</button>\n<button class=\"btn btn-outline-warning\" onclick=\"resetNumFunc()\">Reset</button>\n</div>\n<div class=\"card bg-black border-secondary p-3 position-relative\">\n<small class=\"text-muted d-block text-start font-monospace mb-2\">RESULTADO\n                                                SQL:</small>\n<div class=\"font-monospace text-success fs-4\" id=\"num-output\">15.6789</div>\n<div class=\"text-muted small mt-2\" id=\"num-query-display\">SELECT precio FROM\n                                                Productos;</div>\n</div>\n</div>\n</div>\n<!-- Simulation: Plus Operator vs CONCAT -->\n<div class=\"card bg-dark border-light mb-4 overflow-hidden\" id=\"plus-concat-sim-container\">\n<div class=\"card-header bg-secondary bg-opacity-25 border-bottom border-secondary d-flex justify-content-between align-items-center\">\n<h5 class=\"mb-0 text-white\"><i class=\"fas fa-plus-minus me-2 text-white\"></i>Suma (+) vs Concatenación\n                                        </h5>\n<div class=\"btn-group btn-group-sm\">\n<button class=\"btn btn-outline-light active\" id=\"sim-mode-num\" onclick=\"setPolyMode('NUM')\">123 Números</button>\n<button class=\"btn btn-outline-light\" id=\"sim-mode-txt\" onclick=\"setPolyMode('TXT')\">ABC Texto</button>\n</div>\n</div>\n<div class=\"card-body p-4\">\n<div class=\"d-flex justify-content-center align-items-center gap-3 mb-4\">\n<!-- Col A -->\n<div class=\"text-center\">\n<small class=\"text-muted d-block mb-1\">Columna A</small>\n<div class=\"bg-black border border-secondary rounded p-3 fs-5 font-monospace text-white\" id=\"poly-val-a\">100</div>\n</div>\n<div class=\"display-6 text-warning\" id=\"poly-operator\">+</div>\n<!-- Col B -->\n<div class=\"text-center\">\n<small class=\"text-muted d-block mb-1\">Columna B</small>\n<div class=\"bg-black border border-secondary rounded p-3 fs-5 font-monospace text-white\" id=\"poly-val-b\">50</div>\n</div>\n<div class=\"display-6 text-muted\">=</div>\n<!-- Result -->\n<div class=\"text-center position-relative\">\n<small class=\"text-muted d-block mb-1\">Resultado</small>\n<div class=\"bg-black border border-secondary rounded p-3 fs-4 font-monospace fw-bold\" id=\"poly-result\">150</div>\n<div class=\"position-absolute top-100 start-50 translate-middle-x badge bg-success mt-2\" id=\"poly-badge\">\n                                                    Matemática</div>\n</div>\n</div>\n<div class=\"card bg-black border-secondary p-3 text-center\">\n<div class=\"font-monospace text-warning mb-2\" id=\"poly-query\">SELECT col_a +\n                                                col_b ...</div>\n<div class=\"small text-muted\" id=\"poly-explanation\">\n                                                MariaDB suma los valores matemáticamente.\n                                            </div>\n</div>\n<!-- Special Control for Text Mode -->\n<div class=\"d-none mt-3 text-center animate-fade-in\" id=\"poly-txt-controls\">\n<button class=\"btn btn-sm btn-info\" onclick=\"useConcatFunction()\">\n<i class=\"fas fa-magic me-1\"></i>¡Usar CONCAT()!\n                                            </button>\n</div>\n</div>\n</div>\n<!-- Simulation: Date Machine -->\n<div class=\"card bg-dark border-danger mb-4 overflow-hidden\" id=\"date-sim-container\">\n<div class=\"card-header bg-danger bg-opacity-10 border-bottom border-danger text-white\">\n<h5 class=\"mb-0\"><i class=\"fas fa-calendar-alt me-2 text-danger\"></i>Simulación:\n                                            Funciones de Fecha</h5>\n</div>\n<div class=\"card-body p-4 text-center\">\n<h6 class=\"text-secondary mb-3\">Fecha Original (Columna 'Fecha_Pedido')</h6>\n<div class=\"display-5 text-white fw-bold mb-4\" id=\"date-input\">2023-12-25\n                                            14:30:00</div>\n<div class=\"d-flex flex-wrap justify-content-center gap-2 mb-4\">\n<button class=\"btn btn-outline-danger\" onclick=\"runDateFunc('YEAR')\">YEAR()</button>\n<button class=\"btn btn-outline-danger\" onclick=\"runDateFunc('MONTH')\">MONTH()</button>\n<button class=\"btn btn-outline-danger\" onclick=\"runDateFunc('DAY')\">DAY()</button>\n<button class=\"btn btn-outline-danger\" onclick=\"runDateFunc('DATE_ADD')\">DATE_ADD(x, INTERVAL 1 DAY)</button>\n<button class=\"btn btn-outline-danger\" onclick=\"runDateFunc('NOW')\">NOW()</button>\n<button class=\"btn btn-outline-warning\" onclick=\"resetDateFunc()\">Reset</button>\n</div>\n<div class=\"card bg-black border-secondary p-3 position-relative\">\n<small class=\"text-muted d-block text-start font-monospace mb-2\">RESULTADO\n                                                SQL:</small>\n<div class=\"font-monospace text-danger fs-4\" id=\"date-output\">2023-12-25\n                                                14:30:00</div>\n<div class=\"text-muted small mt-2\" id=\"date-query-display\">SELECT\n                                                fecha_pedido FROM Pedidos;</div>\n</div>\n</div>\n</div>\n<!-- Exercise Manipulation -->\n<h5 class=\"mt-4 text-info\"><i class=\"fas fa-dumbbell me-2\"></i>Ejercicios de\n                                    Manipulación (1-5)</h5>\n<div class=\"accordion accordion-flush bg-transparent\" id=\"accordionDML-Manip\">\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-man-1\" data-bs-toggle=\"collapse\" type=\"button\">1.\n                                                Iniciales del Usuario</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Manip\" id=\"ex-man-1\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Muestra el nombre completo y la primera\n                                                    letra del nombre más la primera del apellido (Iniciales).<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT CONCAT(nombre, ' ', apellido), CONCAT(LEFT(nombre, 1), LEFT(apellido, 1)) FROM Clientes;</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-man-2\" data-bs-toggle=\"collapse\" type=\"button\">2.\n                                                Oferta Mitad de Precio</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Manip\" id=\"ex-man-2\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Muestra el nombre del plato y cuánto\n                                                    costaría si aplicamos un 50% de descuento.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT nombre_plato, (precio_venta * 0.5) as Oferta FROM Platos;</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-man-3\" data-bs-toggle=\"collapse\" type=\"button\">3.\n                                                Longitud de Nombres</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Manip\" id=\"ex-man-3\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Muestra los clientes cuyo nombre tenga\n                                                    más de 6 letras.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT nombre FROM Clientes WHERE LENGTH(nombre) &gt; 6;</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-man-4\" data-bs-toggle=\"collapse\" type=\"button\">4.\n                                                Precios Redondeados</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Manip\" id=\"ex-man-4\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Muestra el nombre del plato y su precio\n                                                    redondeado a cero decimales.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT nombre_plato, ROUND(precio_venta, 0) FROM Platos;</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-man-5\" data-bs-toggle=\"collapse\" type=\"button\">5.\n                                                Emails en Minúsculas</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Manip\" id=\"ex-man-5\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Selecciona los emails de los clientes y\n                                                    conviértelos todos a minúsculas.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT LOWER(email) FROM Clientes;</pre>\n</details>\n</div>\n</div>\n</div></div></article><article class=\"card bg-glass border-0 shadow-sm p-4 mb-4\" id=\"dml-limit\">\n<h4 class=\"text-white\"><i class=\"fas fa-list-ol me-2 text-primary\"></i>2.1c Control de\n                                    Filas (LIMIT y OFFSET)</h4>\n<p>Cuando tienes miles de filas, no quieres traerlas todas. <code>LIMIT</code> te dice\n                                    \"cuántas\" y <code>OFFSET</code> te dice \"desde dónde\".</p>\n<!-- Animation: Limit & Pagination -->\n<div class=\"card bg-dark border-primary mb-4 overflow-hidden position-relative\" id=\"limit-animation-container\">\n<div class=\"card-header bg-primary bg-opacity-10 border-bottom border-primary d-flex justify-content-between align-items-center\">\n<h5 class=\"mb-0 text-white\"><i class=\"fas fa-layer-group me-2 text-primary\"></i>Simulación: Paginación\n                                        </h5>\n<div class=\"code-badge bg-black border border-primary rounded px-3 py-1 font-monospace text-info small d-none d-md-block shadow-sm\">\n                                            SELECT * FROM Posts <span class=\"text-warning\" id=\"limit-query-text\">LIMIT\n                                                3</span>\n</div>\n</div>\n<div class=\"card-body p-0 position-relative\" style=\"height: 400px; background: #0f1215;\">\n<div class=\"d-flex justify-content-center h-100 p-3 gap-4\">\n<!-- Database Rows (Source) -->\n<div class=\"d-flex flex-column align-items-center\" style=\"width: 40%;\">\n<h6 class=\"text-muted text-center mb-2 small uppercase\">BASE DE DATOS\n                                                    (10 Posts)</h6>\n<div class=\"d-flex flex-column gap-1 w-100 position-relative\" id=\"limit-source-rows\">\n<!-- Generated by JS -->\n</div>\n</div>\n<!-- Controls -->\n<div class=\"d-flex flex-column justify-content-center align-items-center gap-3\" style=\"width: 30%;\">\n<div class=\"text-center\">\n<h6 class=\"text-white mb-2\">Paginador</h6>\n<div class=\"btn-group w-100\">\n<button class=\"btn btn-sm btn-outline-light\" onclick=\"prevPage()\"><i class=\"fas fa-chevron-left\"></i></button>\n<span class=\"btn btn-sm btn-dark text-white border-secondary\" id=\"page-indicator\" style=\"width: 100px;\">Página 1</span>\n<button class=\"btn btn-sm btn-outline-light\" onclick=\"nextPage()\"><i class=\"fas fa-chevron-right\"></i></button>\n</div>\n</div>\n<div class=\"card bg-black border-secondary p-2 w-100\">\n<small class=\"text-muted d-block mb-1\">LIMIT (Tamaño pág):</small>\n<select class=\"form-select form-select-sm bg-dark text-white border-secondary\" id=\"limit-select\" onchange=\"updateLimitSimulation()\">\n<option value=\"3\">3 filas</option>\n<option value=\"5\">5 filas</option>\n<option value=\"2\">2 filas</option>\n</select>\n</div>\n<div class=\"alert alert-dark border-secondary p-2 small text-center text-muted mb-0\">\n<i class=\"fas fa-info-circle me-1\"></i>\n<span id=\"offset-explanation\">OFFSET = (Pag - 1) * Limit</span>\n</div>\n</div>\n<!-- Visual Result (User view) -->\n<div class=\"d-flex flex-column align-items-center\" style=\"width: 30%;\">\n<h6 class=\"text-info text-center mb-2 small uppercase\">LO QUE VES</h6>\n<div class=\"card bg-black border-secondary w-100 h-100 p-2 overflow-hidden position-relative\">\n<div class=\"d-flex flex-column gap-2\" id=\"limit-result-view\">\n<!-- Result items -->\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n<div class=\"alert alert-info bg-opacity-10 border-info\">\n<i class=\"fas fa-lightbulb me-2 text-info\"></i><strong>¿Sabías que...?</strong>\n                                    Puedes escribir la paginación más rápido usando una sola coma:\n                                    <br/>\n<code>LIMIT 10 OFFSET 5</code> es igual a <code>LIMIT 5, 10</code>.\n                                    <br/>\n<small class=\"text-muted\">¡Cuidado! En la sintaxis corta, el primer número es el\n                                        <strong>SALTO</strong> (Offset) y el segundo es la <strong>CANTIDAD</strong>\n                                        (Limit).</small>\n</div>\n<h5 class=\"mt-4 text-info\">Ejemplos Prácticos</h5>\n<pre><code class=\"language-sql\">-- Traer solo los primeros 5 empleados\nSELECT * FROM Empleados LIMIT 5;\n\n-- Traer los 3 productos más caros (Combinado con ORDER BY)\nSELECT nombre, precio FROM Productos ORDER BY precio DESC LIMIT 3;</code></pre>\n</article>",
  "3": "<article class=\"card bg-glass border-0 shadow-sm p-4 mb-4\" id=\"dml-aggregates\">\n<h3 class=\"text-white\"><i class=\"fas fa-calculator me-2 text-warning\"></i>2.2 Funciones\n                                    de Agregado</h3>\n<p>Las funciones de agregado toman <strong>muchas filas</strong> y devuelven <strong>un\n                                        solo resultado</strong>. Son esenciales para sacar estadísticas globales.</p>\n<h5 class=\"text-info mt-4\">Las 5 Fantásticas</h5>\n<div class=\"row row-cols-1 row-cols-md-5 g-2 text-center mb-4\">\n<div class=\"col\">\n<div class=\"p-2 border border-secondary rounded bg-dark\"><strong class=\"text-success d-block\">COUNT()</strong>Cuenta filas</div>\n</div>\n<div class=\"col\">\n<div class=\"p-2 border border-secondary rounded bg-dark\"><strong class=\"text-primary d-block\">SUM()</strong>Suma valores</div>\n</div>\n<div class=\"col\">\n<div class=\"p-2 border border-secondary rounded bg-dark\"><strong class=\"text-info d-block\">AVG()</strong>Promedio</div>\n</div>\n<div class=\"col\">\n<div class=\"p-2 border border-secondary rounded bg-dark\"><strong class=\"text-warning d-block\">MAX()</strong>Máximo</div>\n</div>\n<div class=\"col\">\n<div class=\"p-2 border border-secondary rounded bg-dark\"><strong class=\"text-danger d-block\">MIN()</strong>Mínimo</div>\n</div>\n</div>\n<!-- Animation: SUM vs COUNT (Curry) -->\n<div class=\"card bg-dark border-warning mb-4 overflow-hidden position-relative\" id=\"sum-count-animation-container\">\n<div class=\"card-header bg-warning bg-opacity-10 border-bottom border-warning d-flex justify-content-between align-items-center\">\n<h5 class=\"mb-0 text-white\"><i class=\"fas fa-basketball-ball me-2 text-warning\"></i>Simulación: SUM vs\n                                            COUNT</h5>\n<div class=\"code-badge bg-black border border-warning rounded px-3 py-1 font-monospace text-warning small d-none d-md-block shadow-sm\">\n                                            SELECT <span class=\"fw-bold\" id=\"sc-func-name\">...</span>(Puntos) FROM\n                                            Partidos WHERE Jugador = 'Curry'\n                                        </div>\n</div>\n<div class=\"card-body p-0 position-relative\" style=\"height: 350px; background: #1a1a1a;\">\n<div class=\"d-flex justify-content-center align-items-center h-100 p-3 gap-5\">\n<!-- Table Data -->\n<div class=\"position-relative p-2 border border-secondary rounded bg-dark\" id=\"sc-table\">\n<h6 class=\"text-info text-center mb-2\">Tabla Partidos</h6>\n<div class=\"d-flex flex-column gap-1 font-monospace small\" id=\"sc-rows\">\n<!-- Dynamic Rows -->\n</div>\n</div>\n<!-- Controls & Result -->\n<div class=\"d-flex flex-column align-items-center gap-3\" style=\"width: 250px;\">\n<h6 class=\"text-white text-center\">¿Cuántos puntos ha metido Curry?</h6>\n<div class=\"d-flex gap-2 w-100\">\n<button class=\"btn btn-outline-danger flex-grow-1\" onclick=\"startCurryAnimation('COUNT')\">\n<i class=\"fas fa-calculator me-1\"></i>COUNT\n                                                    </button>\n<button class=\"btn btn-outline-success flex-grow-1\" onclick=\"startCurryAnimation('SUM')\">\n<i class=\"fas fa-plus-circle me-1\"></i>SUM\n                                                    </button>\n</div>\n<div class=\"card bg-black border-secondary w-100 p-3 text-center position-relative overflow-hidden\">\n<small class=\"text-muted d-block uppercase mb-1\">RESULTADO</small>\n<div class=\"display-4 fw-bold text-white\" id=\"sc-result\">?</div>\n<div class=\"small mt-2 text-muted\" id=\"sc-feedback\" style=\"min-height: 2.4em; line-height: 1.2;\">Selecciona una\n                                                        función para calcular.</div>\n</div>\n</div>\n</div>\n<!-- Highlight Overlay for Animation -->\n<div class=\"position-absolute bg-warning bg-opacity-25 border border-warning d-none\" id=\"sc-highlight\" style=\"transition: all 0.3s ease; pointer-events: none; z-index: 50;\"></div>\n</div>\n</div>\n<h5 class=\"mt-4 text-info\"><i class=\"fas fa-dumbbell me-2\"></i>Ejercicios Básicos de\n                                    Agregación (1-4)</h5>\n<div class=\"accordion accordion-flush bg-transparent\" id=\"accordionDML-Agg-Basic\">\n<!-- Ex 1 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-agg-1\" data-bs-toggle=\"collapse\" type=\"button\">1.\n                                                Contar Platos</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Agg-Basic\" id=\"ex-agg-1\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> ¿Cuántos platos hay en total en la\n                                                    carta?<br/><span class=\"badge bg-info text-dark mb-2\">Contexto:\n                                                        Arepazo</span></p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT COUNT(*) FROM Platos;</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ex 2 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-agg-2\" data-bs-toggle=\"collapse\" type=\"button\">2.\n                                                Precio Promedio</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Agg-Basic\" id=\"ex-agg-2\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> ¿Cuál es el precio promedio de venta de\n                                                    todos los platos?<br/><span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT AVG(precio_venta) FROM Platos;</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ex 3 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-agg-3\" data-bs-toggle=\"collapse\" type=\"button\">3.\n                                                Max y Min</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Agg-Basic\" id=\"ex-agg-3\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Muestra el precio máximo y el precio\n                                                    mínimo en una sola consulta.<br/><span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT MAX(precio_venta), MIN(precio_venta) FROM Platos;</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ex 4 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-agg-4\" data-bs-toggle=\"collapse\" type=\"button\">4.\n                                                Total Dinero</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Agg-Basic\" id=\"ex-agg-4\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Calcula la suma total de dinero de todos\n                                                    los pedidos registrados.<br/><span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT SUM(total_pedido) FROM Pedidos;</pre>\n</details>\n</div>\n</div>\n</div>\n</div>\n</article><article class=\"card bg-glass border-0 shadow-sm p-4 mb-4 position-relative overflow-hidden\" id=\"dml-groupby\">\n<h3 class=\"text-white\"><i class=\"fas fa-layer-group me-2 text-warning\"></i>2.3 Group By\n                                </h3>\n<div class=\"alert alert-warning bg-opacity-10 border-warning text-warning\">\n<i class=\"fas fa-lightbulb me-2\"></i><strong>Concepto Clave:</strong> Cuando\n                                    agrupamos (GROUP BY), las filas individuales se \"colapsan\". Solo podemos ver el\n                                    campo por el que agrupamos y el resultado de una función matemática sobre los demás.\n                                </div>\n<!-- Interactive Demo Container -->\n<div class=\"card bg-dark border-light mb-4 text-white\" id=\"groupby-interactive-demo\">\n<div class=\"card-header bg-transparent border-bottom border-secondary d-flex justify-content-between align-items-center\">\n<h5 class=\"mb-0\"><i class=\"fas fa-hand-pointer me-2\"></i>Demo Interactiva: NBA\n                                            Player Stats</h5>\n<button class=\"btn btn-sm btn-outline-info\" onclick=\"resetGroupByDemo()\">Resetear\n                                            Tabla</button>\n</div>\n<div class=\"card-body\">\n<p class=\"small text-muted mb-2\">Haz clic en el encabezado\n                                            <strong>\"Team\"</strong> para agrupar por equipo.\n                                        </p>\n<div class=\"table-responsive\">\n<table class=\"table table-dark table-hover table-bordered\" id=\"demo-table\">\n<thead>\n<tr id=\"demo-header-row\"></tr>\n</thead>\n<tbody id=\"demo-body-row\"></tbody>\n</table>\n</div>\n<div class=\"d-none mt-3 animate-fade-in\" id=\"aggregation-controls\">\n<label class=\"form-label text-info\">¿Qué quieres saber de los\n                                                Puntos?</label>\n<div class=\"d-flex gap-2\">\n<button class=\"btn btn-sm btn-outline-light\" onclick=\"applyAggregation('SUM')\">SUM</button>\n<button class=\"btn btn-sm btn-outline-light\" onclick=\"applyAggregation('AVG')\">AVG</button>\n<button class=\"btn btn-sm btn-outline-light\" onclick=\"applyAggregation('MAX')\">MAX</button>\n</div>\n</div>\n<div class=\"mt-3 p-3 bg-primary bg-opacity-25 rounded d-none\" id=\"demo-explanation\">\n</div>\n</div>\n</div>\n<pre><code class=\"language-sql\">-- Ejemplo real NBA\nSELECT Equipo, SUM(Puntos) as Puntos_Totales FROM Jugadores GROUP BY Equipo;</code></pre>\n<h5 class=\"mt-4 text-info\" id=\"dml-having\">Filtrando Grupos (HAVING)</h5>\n<div class=\"alert alert-info bg-opacity-10 border-info\">\n<i class=\"fas fa-filter me-2\"></i><strong>¿Diferencia con WHERE?</strong>\n<ul>\n<li><strong>WHERE:</strong> Filtra filas <em>antes</em> de agrupar.</li>\n<li><strong>HAVING:</strong> Filtra grupos <em>después</em> de agrupar.</li>\n</ul>\n</div>\n<pre><code class=\"language-sql\">SELECT cliente_id, SUM(total) FROM Pedidos GROUP BY cliente_id HAVING SUM(total) &gt; 1000;</code></pre>\n<h5 class=\"mt-4 text-info\"><i class=\"fas fa-dumbbell me-2\"></i>Ejercicios de Group By\n                                    (1-6)</h5>\n<div class=\"accordion accordion-flush bg-transparent\" id=\"accordionDML-Agg\">\n<!-- Ex 5 -> 1 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-agg-5\" data-bs-toggle=\"collapse\" type=\"button\">1.\n                                                Platos por Categoría</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Agg\" id=\"ex-agg-5\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Muestra cuántos platos hay en cada\n                                                    categoría.<br/><span class=\"badge bg-info text-dark mb-2\">Contexto:\n                                                        Arepazo</span></p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT categoria, COUNT(*) FROM Platos GROUP BY categoria;</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ex 6 -> 2 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-agg-6\" data-bs-toggle=\"collapse\" type=\"button\">2.\n                                                Promedio por Categoría</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Agg\" id=\"ex-agg-6\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> ¿Cuál es el precio promedio de cada\n                                                    categoría?<br/><span class=\"badge bg-info text-dark mb-2\">Contexto:\n                                                        Arepazo</span></p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT categoria, AVG(precio_venta) FROM Platos GROUP BY categoria;</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ex 7 -> 3 (Having) -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-agg-7\" data-bs-toggle=\"collapse\" type=\"button\">3.\n                                                Filtrar Grupos (HAVING)</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Agg\" id=\"ex-agg-7\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Muestra las categorías que tengan más de\n                                                    5 platos.<br/><span class=\"badge bg-info text-dark mb-2\">Contexto:\n                                                        Arepazo</span></p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT categoria, COUNT(*) FROM Platos GROUP BY categoria HAVING COUNT(*) &gt; 5;</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ex 8 -> 4 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-agg-8\" data-bs-toggle=\"collapse\" type=\"button\">4.\n                                                Ingredientes más caros</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Agg\" id=\"ex-agg-8\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Precio promedio de ingredientes por\n                                                    unidad de medida.<br/><span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT unidad_almacen, AVG(precio_kg) FROM Ingredientes GROUP BY unidad_almacen;</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ex 9 -> 5 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-agg-9\" data-bs-toggle=\"collapse\" type=\"button\">5.\n                                                Pedidos por Cliente</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Agg\" id=\"ex-agg-9\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> ID del cliente y cuántos pedidos ha\n                                                    realizado.<br/><span class=\"badge bg-info text-dark mb-2\">Contexto:\n                                                        Arepazo</span></p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT cliente_id, COUNT(*) FROM Pedidos GROUP BY cliente_id;</pre>\n</details>\n</div>\n</div>\n</div>\n<!-- Ex 10 -> 6 -->\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-agg-10\" data-bs-toggle=\"collapse\" type=\"button\">6.\n                                                Suma condicional</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Agg\" id=\"ex-agg-10\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Gasto total agrupado por tipo de\n                                                    pedido.<br/><span class=\"badge bg-info text-dark mb-2\">Contexto:\n                                                        Arepazo</span></p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT tipo_pedido, SUM(total_pedido) FROM Pedidos GROUP BY tipo_pedido;</pre>\n</details>\n</div>\n</div>\n</div>\n</div>\n</article><div class='alert alert-danger'>No se encontró el elemento dml-having</div><article class=\"card bg-glass border-0 shadow-sm p-4 mb-4\" id=\"dml-joins\">\n<h3 class=\"text-white\"><i class=\"fas fa-project-diagram me-2 text-primary\"></i>2.4 Joins\n                                    (Unir tablas)</h3>\n<p>La potencia real de SQL viene de mezclar datos de tablas distintas. La clave para que\n                                    funcione es el campo en común (Foreign Key).</p>\n<!-- Visual Guide -->\n<div class=\"row mb-4\">\n<div class=\"col-md-6\">\n<div class=\"p-3 border rounded border-secondary bg-dark text-center h-100\">\n<h5 class=\"text-success\">INNER JOIN</h5>\n<div class=\"d-flex justify-content-center align-items-center mb-2\" style=\"height: 100px;\">\n<!-- Visual Representation using CSS shapes -->\n<div class=\"rounded-circle border border-light d-flex align-items-center justify-content-center\" style=\"width: 80px; height: 80px; margin-right: -20px; z-index: 1; background: rgba(255, 255, 255, 0.1);\">\n                                                    Tabla A</div>\n<div class=\"rounded-circle bg-success d-flex align-items-center justify-content-center fw-bold text-white shadow\" style=\"width: 60px; height: 60px; z-index: 3;\">Match</div>\n<div class=\"rounded-circle border border-light d-flex align-items-center justify-content-center\" style=\"width: 80px; height: 80px; margin-left: -20px; z-index: 1; background: rgba(255, 255, 255, 0.1);\">\n                                                    Tabla B</div>\n</div>\n<p class=\"small text-muted\">\"Solo muéstrame las parejas perfectas\". Si un\n                                                cliente no ha comprado, no sale. Si un pedido no tiene cliente, no sale.\n                                            </p>\n</div>\n</div>\n<div class=\"col-md-6\">\n<div class=\"p-3 border rounded border-secondary bg-dark text-center h-100\">\n<h5 class=\"text-warning\">LEFT JOIN</h5>\n<div class=\"d-flex justify-content-center align-items-center mb-2\" style=\"height: 100px;\">\n<div class=\"rounded-circle bg-warning border border-warning d-flex align-items-center justify-content-center text-dark fw-bold shadow\" style=\"width: 80px; height: 80px; margin-right: -20px; z-index: 2;\">\n                                                    Tabla A</div>\n<div class=\"rounded-circle border border-light d-flex align-items-center justify-content-center\" style=\"width: 80px; height: 80px; margin-left: -20px; z-index: 1; background: rgba(255, 255, 255, 0.1);\">\n                                                    Tabla B</div>\n</div>\n<p class=\"small text-muted\">\"Todo lo mí (izquierda) y lo que encuentres de\n                                                ellos\". Muestra TODOS los clientes, compren o no.</p>\n</div>\n</div>\n</div>\n<!-- Animation: Inner Join -->\n<div class=\"card bg-dark border-secondary mb-4 overflow-hidden position-relative\" id=\"join-animation-container\">\n<div class=\"card-header bg-transparent border-bottom border-secondary d-flex justify-content-between align-items-center\">\n<h5 class=\"mb-0 text-white\"><i class=\"fas fa-play-circle me-2 text-primary\"></i>Animación: Inner Join\n                                        </h5>\n<div class=\"code-badge bg-black border border-secondary rounded px-3 py-1 font-monospace text-info small d-none d-md-block shadow-sm\">\n                                            SELECT * FROM Clientes C <strong>INNER JOIN</strong> Pedidos P\n                                            <strong>ON</strong> C.id = P.cliente_id\n                                        </div>\n<button class=\"btn btn-sm btn-primary\" onclick=\"startJoinAnimation()\">\n<i class=\"fas fa-play me-1\"></i> Iniciar\n                                        </button>\n</div>\n<div class=\"card-body p-0 position-relative\" style=\"height: 400px; background: #111;\">\n<!-- Visualization Area -->\n<div class=\"d-flex justify-content-between h-100 p-3 position-relative\">\n<!-- Table A (Left) -->\n<div class=\"join-table-container text-center\" style=\"width: 25%;\">\n<h6 class=\"text-info fw-bold mb-3\">Tabla Clientes (A)</h6>\n<div class=\"d-flex flex-column gap-2\" id=\"table-a-rows\">\n<!-- Dynamic Content -->\n</div>\n</div>\n<!-- Result Area (Center) -->\n<div class=\"join-result-container text-center d-flex flex-column justify-content-start pt-5\" style=\"width: 40%;\">\n<h6 class=\"text-success fw-bold mb-3 opacity-0\" id=\"result-title\">\n                                                    RESULTADO (MATCH)</h6>\n<div class=\"d-flex flex-column gap-2 align-items-center w-100\" id=\"join-result-rows\">\n<!-- Results will drop here -->\n</div>\n</div>\n<!-- Table B (Right) -->\n<div class=\"join-table-container text-center\" style=\"width: 25%;\">\n<h6 class=\"text-warning fw-bold mb-3\">Tabla Pedidos (B)</h6>\n<div class=\"d-flex flex-column gap-2\" id=\"table-b-rows\">\n<!-- Dynamic Content -->\n</div>\n</div>\n</div>\n<!-- Explanation Overlay -->\n<div class=\"position-absolute bottom-0 w-100 p-2 bg-dark bg-opacity-75 text-center text-white small\" id=\"join-explanation\" style=\"border-top: 1px solid #333;\">\n                                            Dale a \"Iniciar\" para ver cómo el Inner Join busca coincidencias.\n                                        </div>\n</div>\n<!-- Animation: Ambiguous Column Error -->\n<div class=\"card bg-dark border-danger mb-4 overflow-hidden position-relative\" id=\"ambiguous-animation-container\">\n<div class=\"card-header bg-danger bg-opacity-25 border-bottom border-danger d-flex justify-content-between align-items-center\">\n<h5 class=\"mb-0 text-white\"><i class=\"fas fa-exclamation-triangle me-2 text-danger\"></i>Error:\n                                                Columna Ambigua</h5>\n<div class=\"code-badge bg-black border border-danger rounded px-3 py-1 font-monospace text-danger small d-none d-md-block shadow-sm\" id=\"ambiguous-query-display\">\n                                                SELECT <span class=\"text-decoration-underline fw-bold\">id</span>,\n                                                nombre, item FROM Clientes JOIN Pedidos...\n                                            </div>\n<button class=\"btn btn-sm btn-danger\" onclick=\"startAmbiguousAnimation()\">\n<i class=\"fas fa-play me-1\"></i> Simular Error\n                                            </button>\n</div>\n<div class=\"card-body p-0 position-relative\" style=\"height: 350px; background: #2c0b0e;\">\n<div class=\"d-flex justify-content-center align-items-center h-100 p-3 gap-4\">\n<!-- Table A -->\n<div class=\"position-relative p-2 border border-secondary rounded bg-dark\" id=\"ambiguous-table-a\">\n<h6 class=\"text-info text-center mb-2\">Tabla Clientes</h6>\n<div class=\"d-flex flex-column gap-1 font-monospace small\">\n<div class=\"bg-secondary bg-opacity-25 p-1 px-2 rounded d-flex justify-content-between\">\n<span class=\"text-danger fw-bold column-id\">id</span>\n<span>nombre</span>\n</div>\n<div class=\"text-muted p-1\">1, Ana...</div>\n<div class=\"text-muted p-1\">2, Bob...</div>\n</div>\n<!-- Arrow -->\n<div class=\"position-absolute top-0 start-50 translate-middle mt-n3 d-none text-white fs-4 glitch-arrow\" style=\"z-index:10; top: -10px;\">?</div>\n</div>\n<div class=\"text-center text-white display-6\">\n<i class=\"fas fa-times-circle text-danger opacity-50\" id=\"ambiguous-error-icon\" style=\"font-size: 3rem;\"></i>\n</div>\n<!-- Table B -->\n<div class=\"position-relative p-2 border border-secondary rounded bg-dark\" id=\"ambiguous-table-b\">\n<h6 class=\"text-warning text-center mb-2\">Tabla Pedidos</h6>\n<div class=\"d-flex flex-column gap-1 font-monospace small\">\n<div class=\"bg-secondary bg-opacity-25 p-1 px-2 rounded d-flex justify-content-between\">\n<span class=\"text-danger fw-bold column-id\">id</span>\n<span>item</span>\n</div>\n<div class=\"text-muted p-1\">10, Pizza...</div>\n<div class=\"text-muted p-1\">11, Sushi...</div>\n</div>\n</div>\n</div>\n<!-- Error Overlay -->\n<div class=\"position-absolute top-50 start-50 translate-middle w-75 p-3 bg-black border border-danger rounded shadow text-center d-none\" id=\"ambiguous-overlay\" style=\"z-index: 20;\">\n<h5 class=\"text-danger\"><i class=\"fas fa-bug\"></i> Error SQL: 1052</h5>\n<p class=\"text-white mb-2\">Column 'id' in field list is ambiguous</p>\n<small class=\"text-muted d-block mb-3\">SQL no sabe si te refieres al\n                                                    'id' de Clientes o al 'id' de Pedidos.</small>\n<button class=\"btn btn-outline-success btn-sm pulse-button\" onclick=\"fixAmbiguousError()\">\n<i class=\"fas fa-magic me-2\"></i>Aplicar Solución: Alias\n                                                </button>\n</div>\n<!-- Explanation Bar -->\n<div class=\"position-absolute bottom-0 w-100 p-2 bg-dark bg-opacity-75 text-center text-white small\" id=\"ambiguous-explanation\" style=\"border-top: 1px solid #500;\">\n                                                Intenta seleccionar 'id' sin decir de qué tabla es.\n                                            </div>\n</div>\n</div>\n<i class=\"fas fa-link me-2\"></i><strong>El \"ON\" es la clave:</strong> Debes decir\n                                    <code>ON tabla1.id = tabla2.fk_id</code> para que el motor sepa cómo pegar las\n                                    filas.\n                                </div>\n<h5 class=\"text-info mt-4\">Patrón de Exclusión (Encontrar lo que NO está)</h5>\n<p>Una de las utilidades más potentes del <code>LEFT JOIN</code> es encontrar datos que\n                                    faltan. Por\n                                    ejemplo: <em>\"Usuarios que NO han comprado nada\"</em>.</p>\n<pre><code class=\"language-sql\">-- 1. Traemos TODOS los usuarios (LEFT JOIN)\n-- 2. Si no tienen pedido, el campo pedido_id será NULL\n-- 3. Filtramos esos NULLs\nSELECT Usuarios.nombre \nFROM Usuarios\nLEFT JOIN Pedidos ON Usuarios.id = Pedidos.usuario_id\nWHERE Pedidos.id IS NULL;</code></pre>\n<!-- Animation: Exclusion Pattern -->\n<div class=\"card bg-dark border-warning mb-4 overflow-hidden position-relative\" id=\"exclusion-animation-container\">\n<div class=\"card-header bg-warning bg-opacity-10 border-bottom border-warning d-flex justify-content-between align-items-center\">\n<h5 class=\"mb-0 text-white\"><i class=\"fas fa-search-minus me-2 text-warning\"></i>Simulación: Encontrar\n                                            sin pareja</h5>\n<div class=\"code-badge bg-black border border-warning rounded px-3 py-1 font-monospace text-warning small d-none d-md-block shadow-sm\" id=\"exclusion-query-display\">\n                                            SELECT U.nombre FROM Usuarios U <strong>LEFT JOIN</strong> Pedidos P...\n                                            <strong>WHERE P.id IS NULL</strong>\n</div>\n</div>\n<div class=\"card-body p-0 position-relative\" style=\"height: 420px; background: #1a1a1a;\">\n<div class=\"d-flex justify-content-center h-100 p-3 gap-4\">\n<!-- Table Users (Left) -->\n<div class=\"d-flex flex-column align-items-center\" style=\"width: 30%;\">\n<h6 class=\"text-info text-center mb-2 small uppercase\">USUARIOS (Left)\n                                                </h6>\n<div class=\"d-flex flex-column gap-2 w-100 position-relative\" id=\"excl-users-rows\">\n<!-- Init via JS -->\n</div>\n</div>\n<!-- Connection Zone -->\n<div class=\"d-flex flex-column justify-content-center align-items-center\" style=\"width: 10%;\">\n<i class=\"fas fa-exchange-alt text-muted fa-2x opacity-50\"></i>\n</div>\n<!-- Table Orders (Right) -->\n<div class=\"d-flex flex-column align-items-center\" style=\"width: 30%;\">\n<h6 class=\"text-warning text-center mb-2 small uppercase\">PEDIDOS\n                                                    (Right)</h6>\n<div class=\"d-flex flex-column gap-2 w-100 position-relative\" id=\"excl-orders-rows\">\n<!-- Init via JS -->\n</div>\n</div>\n<!-- Result Bucket -->\n<div class=\"d-flex flex-column align-items-center justify-content-start border-start border-secondary ps-3\" style=\"width: 25%;\">\n<h6 class=\"text-light text-center mb-2 small uppercase\">RESULTADO (IS\n                                                    NULL)</h6>\n<div class=\"card bg-black border-secondary w-100 h-100 p-2 overflow-auto\" id=\"excl-result-area\">\n<div class=\"text-muted small text-center mt-4 fst-italic\">Aquí\n                                                        caerán\n                                                        los \"solteros\"...</div>\n</div>\n</div>\n</div>\n<!-- Controls Overlay -->\n<div class=\"position-absolute bottom-0 w-100 p-3 d-flex justify-content-center gap-3 bg-dark bg-opacity-90 border-top border-secondary\">\n<button class=\"btn btn-warning btn-sm fw-bold\" onclick=\"runExclusionSim()\">\n<i class=\"fas fa-play me-1\"></i> Simular Exclusión\n                                            </button>\n<button class=\"btn btn-outline-light btn-sm\" onclick=\"resetExclusionSim()\">\n<i class=\"fas fa-undo me-1\"></i> Reiniciar\n                                            </button>\n</div>\n</div>\n</div>\n<!-- Exercises Joins -->\n<h5 class=\"mt-4 text-info\"><i class=\"fas fa-dumbbell me-2\"></i>Ejercicios de Joins\n                                    (1-10)</h5>\n<div class=\"accordion accordion-flush bg-transparent\" id=\"accordionDML-Joins\">\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-join-1\" data-bs-toggle=\"collapse\" type=\"button\">1.\n                                                Pedidos y sus Clientes (Inner)</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Joins\" id=\"ex-join-1\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Muestra el ID del pedido, la fecha y el\n                                                    nombre del\n                                                    cliente que lo\n                                                    hizo. Solo nos interesan los pedidos que tienen un cliente\n                                                    válido.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT Pedidos.pedido_id, Pedidos.fecha_hora, Clientes.nombre \nFROM Pedidos \nINNER JOIN Clientes ON Pedidos.cliente_id = Clientes.cliente_id;</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-join-2\" data-bs-toggle=\"collapse\" type=\"button\">2.\n                                                Todos los Clientes (Left)</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Joins\" id=\"ex-join-2\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Muestra TODOS los clientes y el ID de sus\n                                                    pedidos (si\n                                                    tienen). Queremos ver incluso a los clientes que no han comprado\n                                                    nada\n                                                    (aparecerán con NULL).<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT Clientes.nombre, Pedidos.pedido_id \nFROM Clientes \nLEFT JOIN Pedidos ON Clientes.cliente_id = Pedidos.cliente_id;</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-join-3\" data-bs-toggle=\"collapse\" type=\"button\">3.\n                                                Platos e Ingredientes (Tabla Puente)</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Joins\" id=\"ex-join-3\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> En bases de datos N:M, unimos 3 tablas.\n                                                    Muestra el\n                                                    nombre del Plato, el ingrediente que lleva y la cantidad necesaria.\n                                                    (Platos -&gt;\n                                                    Recetas -&gt; Ingredientes).<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT Platos.nombre_plato, Ingredientes.nombre_ing, Recetas.cantidad\nFROM Platos\nINNER JOIN Recetas ON Platos.plato_id = Recetas.plato_id\nINNER JOIN Ingredientes ON Recetas.ingrediente_id = Ingredientes.ingrediente_id;</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-join-4\" data-bs-toggle=\"collapse\" type=\"button\">4.\n                                                Clientes SIN pedidos (Is Null)</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Joins\" id=\"ex-join-4\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Encuentra a los clientes que NUNCA han\n                                                    comprado nada.\n                                                    (Pista: Usa LEFT JOIN y busca el NULL).<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT Clientes.nombre \nFROM Clientes \nLEFT JOIN Pedidos ON Clientes.cliente_id = Pedidos.cliente_id \nWHERE Pedidos.pedido_id IS NULL;</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-join-5\" data-bs-toggle=\"collapse\" type=\"button\">5.\n                                                Jugadores y sus Equipos (NBA)</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Joins\" id=\"ex-join-5\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Muestra el nombre del jugador, su\n                                                    apellido y la\n                                                    ciudad del equipo donde juega.<br/>\n<span class=\"badge bg-warning text-dark mb-2\">Contexto: NBA</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT jugadores.nombre, jugadores.apellido1, equipos.ciudad \nFROM jugadores \nINNER JOIN equipos ON jugadores.id_equipo = equipos.id;</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-join-6\" data-bs-toggle=\"collapse\" type=\"button\">6.\n                                                Equipos Locales en Partidos</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Joins\" id=\"ex-join-6\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Muestra la fecha del partido y el nombre\n                                                    del equipo\n                                                    local.<br/>\n<span class=\"badge bg-warning text-dark mb-2\">Contexto: NBA</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT partidos.fecha, equipos.nombre \nFROM partidos \nINNER JOIN equipos ON partidos.id_equipoLocal = equipos.id;</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-join-7\" data-bs-toggle=\"collapse\" type=\"button\">7.\n                                                Alias de Tabla (AS)</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Joins\" id=\"ex-join-7\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Reescribe la consulta anterior usando\n                                                    alias cortos\n                                                    ('p' para partidos, 'e' para equipos) para hacerla más legible.<br/>\n<span class=\"badge bg-warning text-dark mb-2\">Contexto: NBA</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT p.fecha, e.nombre \nFROM partidos p \nINNER JOIN equipos e ON p.id_equipoLocal = e.id;</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-join-8\" data-bs-toggle=\"collapse\" type=\"button\">8.\n                                                Total gastado por Cliente</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Joins\" id=\"ex-join-8\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Combina JOIN con SUM y GROUP BY. Muestra\n                                                    el nombre\n                                                    del cliente y cuánto ha gastado en total.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT c.nombre, SUM(p.total_pedido) \nFROM Clientes c \nINNER JOIN Pedidos p ON c.cliente_id = p.cliente_id \nGROUP BY c.cliente_id;</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-join-9\" data-bs-toggle=\"collapse\" type=\"button\">9.\n                                                Self Join (Jefe y Empleado)</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Joins\" id=\"ex-join-9\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Si la tabla Empleados tiene un campo\n                                                    <code>jefe_id</code>, únete a la misma tabla para ver el nombre del\n                                                    empleado y\n                                                    el nombre de su jefe.<br/>\n<span class=\"badge bg-secondary mb-2\">Contexto: General</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT e.nombre AS Empleado, j.nombre AS Jefe \nFROM Empleados e \nLEFT JOIN Empleados j ON e.jefe_id = j.id;</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-join-10\" data-bs-toggle=\"collapse\" type=\"button\">10.\n                                                Productos y Categoría</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Joins\" id=\"ex-join-10\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Muestra el nombre del producto y el\n                                                    nombre de su\n                                                    categoría (Tabla Categorias).<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT p.nombre, c.nombre_cat \nFROM Productos p \nINNER JOIN Categorias c ON p.cat_id = c.id;</pre>\n</details>\n</div>\n</div>\n</div>\n</div>\n</article>",
  "4": "<article class=\"card bg-glass border-0 shadow-sm p-4 mb-4\" id=\"dml-subqueries\">\n<h3 class=\"text-white\"><i class=\"fas fa-level-down-alt me-2 text-secondary\"></i>2.5\n                                    Subconsultas</h3>\n<p>Una subconsulta es una consulta anidada dentro de otra. Se usa cuando necesitas un\n                                    valor que aún no conoces para filtrar tu consulta principal.</p>\n<div class=\"alert alert-secondary bg-opacity-10\">\n<strong>Objetivo:</strong> Encontrar jugadores que ganan más que el promedio.\n                                    <br/>\n<small>1. Calculo el promedio. 2. Filtro quién gana más que eso.</small>\n</div>\n<pre><code class=\"language-sql\">SELECT nombre, salario \nFROM Jugadores\nWHERE salario &gt; (SELECT AVG(salario) FROM Jugadores);</code></pre>\n<!-- Exercises Subqueries -->\n<h5 class=\"mt-4 text-info\"><i class=\"fas fa-dumbbell me-2\"></i>Ejercicios de\n                                    Subconsultas (1-10)</h5>\n<div class=\"accordion accordion-flush bg-transparent\" id=\"accordionDML-Sub\">\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-sub-1\" data-bs-toggle=\"collapse\" type=\"button\">1.\n                                                Arepas más caras que el promedio</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Sub\" id=\"ex-sub-1\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Muestra las arepas (platos) que cuestan\n                                                    más que\n                                                    el precio promedio de todos los platos.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT nombre_plato, precio_venta \nFROM Platos \nWHERE precio_venta &gt; (SELECT AVG(precio_venta) FROM Platos);</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-sub-2\" data-bs-toggle=\"collapse\" type=\"button\">2.\n                                                Cliente con el pedido más caro</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Sub\" id=\"ex-sub-2\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Muestra el nombre del cliente que hizo el\n                                                    pedido\n                                                    con el importe máximo histórico.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT nombre \nFROM Clientes \nWHERE cliente_id = (\n    SELECT cliente_id FROM Pedidos \n    ORDER BY total_pedido DESC LIMIT 1\n);</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-sub-3\" data-bs-toggle=\"collapse\" type=\"button\">3.\n                                                Platos nunca pedidos (NOT IN)</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Sub\" id=\"ex-sub-3\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Muestra los platos cuyo ID NO aparece en\n                                                    la tabla\n                                                    de detalles de pedidos (Platos nunca vendidos).<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT nombre_plato \nFROM Platos \nWHERE plato_id NOT IN (SELECT DISTINCT plato_id FROM Lineas_Pedido);</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-sub-4\" data-bs-toggle=\"collapse\" type=\"button\">4.\n                                                Jugadores del equipo con más puntos</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Sub\" id=\"ex-sub-4\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Muestra los nombres de los jugadores que\n                                                    pertenecen al equipo que ha anotado más puntos en total.<br/>\n<span class=\"badge bg-primary mb-2\">Contexto: NBA</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT nombre \nFROM Jugadores \nWHERE nombre_equipo = (\n    SELECT Equipo FROM Jugadores GROUP BY Equipo ORDER BY SUM(Puntos) DESC LIMIT 1\n);</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-sub-5\" data-bs-toggle=\"collapse\" type=\"button\">5.\n                                                Clientes que compraron 'Reina Pepiada'</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Sub\" id=\"ex-sub-5\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Obtén los clientes que han pedido\n                                                    específicamente\n                                                    el plato 'Reina Pepiada'. (Requiere unir\n                                                    Clientes-&gt;Pedidos-&gt;Lineas-&gt;Platos).<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT nombre FROM Clientes WHERE cliente_id IN (\n    SELECT cliente_id FROM Pedidos WHERE pedido_id IN (\n        SELECT pedido_id FROM Lineas_Pedido WHERE plato_id = (SELECT plato_id FROM Platos WHERE nombre_plato = 'Reina Pepiada')\n    )\n);</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-sub-6\" data-bs-toggle=\"collapse\" type=\"button\">6.\n                                                Precios superiores al de 'Juan'</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Sub\" id=\"ex-sub-6\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Muestra los pedidos cuyo total es\n                                                    superior al\n                                                    total máximo gastado por el cliente con ID 1.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT * FROM Pedidos \nWHERE total_pedido &gt; (SELECT MAX(total_pedido) FROM Pedidos WHERE cliente_id = 1);</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-sub-7\" data-bs-toggle=\"collapse\" type=\"button\">7.\n                                                EXISTS (Correlacionada)</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Sub\" id=\"ex-sub-7\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Muestra los clientes que SÍ tienen\n                                                    pedidos\n                                                    registrados. Usa EXISTS.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT nombre FROM Clientes c\nWHERE EXISTS (SELECT 1 FROM Pedidos p WHERE p.cliente_id = c.cliente_id);</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-sub-8\" data-bs-toggle=\"collapse\" type=\"button\">8.\n                                                Ingredientes en Recetas Caras</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Sub\" id=\"ex-sub-8\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Muestra los nombres de los ingredientes\n                                                    que se\n                                                    usan en platos que cuestan más de 20.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT nombre_ing FROM Ingredientes WHERE ingrediente_id IN (\n    SELECT ingrediente_id FROM Recetas WHERE plato_id IN (\n        SELECT plato_id FROM Platos WHERE precio_venta &gt; 20\n    )\n);</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-sub-9\" data-bs-toggle=\"collapse\" type=\"button\">9.\n                                                Último pedido registrado</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Sub\" id=\"ex-sub-9\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Muestra todos los detalles del último\n                                                    pedido\n                                                    insertado en la BD (Max ID).<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT * FROM Pedidos WHERE pedido_id = (SELECT MAX(pedido_id) FROM Pedidos);</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-sub-10\" data-bs-toggle=\"collapse\" type=\"button\">10.\n                                                Salario menor al mínimo de otro equipo</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Sub\" id=\"ex-sub-10\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Muestra los jugadores que ganan MENOS que\n                                                    el\n                                                    jugador peor pagado del equipo 'Lakers'.<br/>\n<span class=\"badge bg-primary mb-2\">Contexto: NBA</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                    </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">SELECT nombre FROM Jugadores \nWHERE salario &lt; (SELECT MIN(salario) FROM Jugadores WHERE nombre_equipo = 'Lakers');</pre>\n</details>\n</div>\n</div>\n</div>\n</div>\n</article><section class=\"\" id=\"advanced-queries\">\n<h2 class=\"display-6 fw-bold text-white mb-4 border-bottom pb-2 mt-5\">Consultas Avanzadas</h2>\n<!-- EX 1: Arepazo Profitability -->\n<article class=\"card bg-glass border-0 shadow-sm p-4 mb-4\">\n<h4 class=\"text-info\"><i class=\"fas fa-chart-line me-2\"></i>Rentabilidad Arepazo</h4>\n<p class=\"text-secondary\"><strong>Enunciado:</strong> Calcula la ganancia bruta por plato\n                                restando\n                                el costo de los ingredientes al precio de venta. Ordena por mayor ganancia.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<div class=\"alert alert-info bg-opacity-10 border-info text-info\">\n<i class=\"fas fa-lightbulb me-2\"></i>\n<strong>Lógica:</strong> Unir Platos, Recetas e Ingredientes. Calcular costo sumando\n                                (cantidad *\n                                costo_unitario).\n                            </div>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL</summary>\n<pre><code class=\"language-sql\">SELECT \n    p.nombre_plato, \n    p.precio_venta, \n    SUM(r.cantidad_kg * i.precio_kg) AS costo_ingredientes,\n    (p.precio_venta - SUM(r.cantidad_kg * i.precio_kg)) AS ganancia_bruta\nFROM Platos p\nJOIN Recetas r ON p.plato_id = r.plato_id\nJOIN Ingredientes i ON r.ingrediente_id = i.ingrediente_id\nGROUP BY p.plato_id, p.nombre_plato, p.precio_venta\nORDER BY ganancia_bruta DESC;</code></pre>\n</details>\n</article>\n<!-- EX 2: NBA Standings -->\n<article class=\"card bg-glass border-0 shadow-sm p-4 mb-4\">\n<h4 class=\"text-warning\"><i class=\"fas fa-trophy me-2\"></i>Clasificación NBA</h4>\n<p class=\"text-secondary\"><strong>Enunciado:</strong> Calcula el número total de victorias\n                                por\n                                equipo, sumando las victorias como local y como visitante.<br/>\n<span class=\"badge bg-primary mb-2\">Contexto: NBA</span>\n</p>\n<div class=\"alert alert-warning bg-opacity-10 border-warning text-warning\">\n<i class=\"fas fa-lightbulb me-2\"></i>\n<strong>Lógica:</strong> Usar un CASE condicional para sumar 1 si el equipo ganó (ya sea\n                                local o\n                                visitante).\n                            </div>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL</summary>\n<pre><code class=\"language-sql\">SELECT \n    e.nombre AS equipo,\n    COUNT(CASE \n        WHEN (p.id_equipoLocal = e.id AND p.marcadorLocal &gt; p.marcadorVisitante) OR \n             (p.id_equipoVisitante = e.id AND p.marcadorVisitante &gt; p.marcadorLocal) \n        THEN 1 \n    END) as victorias\nFROM equipos e\nLEFT JOIN partidos p ON e.id = p.id_equipoLocal OR e.id = p.id_equipoVisitante\nGROUP BY e.id, e.nombre\nORDER BY victorias DESC;</code></pre>\n</details>\n</article>\n<!-- EX 3 (NEW): Ingredient Consumption -->\n<article class=\"card bg-glass border-0 shadow-sm p-4 mb-4\">\n<h4 class=\"text-info\"><i class=\"fas fa-utensils me-2\"></i>Consumo Total de Ingredientes</h4>\n<p class=\"text-secondary\"><strong>Enunciado:</strong> Muestra cuántos Kg de cada ingrediente\n                                se\n                                han\n                                consumido basándote en todos los pedidos realizados.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<div class=\"alert alert-info bg-opacity-10 border-info text-info\">\n<i class=\"fas fa-lightbulb me-2\"></i>\n<strong>Lógica:</strong> Lineas_Pedido (cantidad platos) * Recetas (cantidad ingrediente\n                                por\n                                plato). Agrupar por Ingrediente.\n                            </div>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL</summary>\n<pre><code class=\"language-sql\">SELECT \n    i.nombre_ingrediente,\n    SUM(lp.cantidad * r.cantidad_kg) AS total_consumido_kg\nFROM Lineas_Pedido lp\nJOIN Recetas r ON lp.plato_id = r.plato_id\nJOIN Ingredientes i ON r.ingrediente_id = i.ingrediente_id\nGROUP BY i.ingrediente_id, i.nombre_ingrediente\nORDER BY total_consumido_kg DESC;</code></pre>\n</details>\n</article>\n<!-- EX 4 (NEW): Double-Doubles -->\n<article class=\"card bg-glass border-0 shadow-sm p-4 mb-4\">\n<h4 class=\"text-warning\"><i class=\"fas fa-basketball-ball me-2\"></i>Reyes del Doble-Doble\n                            </h4>\n<p class=\"text-secondary\"><strong>Enunciado:</strong> Cuenta en cuántos partidos cada\n                                jugador ha\n                                conseguido un \"Doble-Doble\" (&gt;= 10 en al menos 2 categorías: Puntos, Rebotes o\n                                Asistencias).<br/>\n<span class=\"badge bg-primary mb-2\">Contexto: NBA</span>\n</p>\n<div class=\"alert alert-warning bg-opacity-10 border-warning text-warning\">\n<i class=\"fas fa-lightbulb me-2\"></i>\n<strong>Lógica:</strong> Sumar flags (CASE) de cada categoría. Si la suma &gt;= 2, es un\n                                Doble-Doble.\n                            </div>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL</summary>\n<pre><code class=\"language-sql\">SELECT \n    j.nombre,\n    COUNT(*) as total_doble_dobles\nFROM estadisticasPartido ep\nJOIN jugadores j ON ep.id_jugador = j.id\nWHERE (\n    (CASE WHEN ep.puntos &gt;= 10 THEN 1 ELSE 0 END) +\n    (CASE WHEN ep.rebotes &gt;= 10 THEN 1 ELSE 0 END) +\n    (CASE WHEN ep.asistencias &gt;= 10 THEN 1 ELSE 0 END)\n) &gt;= 2\nGROUP BY j.id, j.nombre\nORDER BY total_doble_dobles DESC;</code></pre>\n</details>\n</article>\n</section>",
  "5": "<section class=\"\" id=\"dml-modification\">\n<h2 class=\"display-6 fw-bold text-white mb-4 border-bottom pb-2 mt-5\">Modificación de\n                            Datos (DML)</h2>\n<article class=\"card bg-glass border-0 shadow-sm p-4 mb-4\" id=\"dml-insert\">\n<h3 class=\"text-success\">3.1 INSERT (Crear)</h3>\n<p class=\"text-secondary mb-3\">\n                                El comando <code>INSERT</code> permite añadir datos de dos formas principales:\n                                introduciendo los valores manualmente o copiándolos desde otra consulta.\n                            </p>\n<div class=\"row g-3 mb-3\">\n<div class=\"col-md-6\">\n<h6 class=\"text-white border-bottom border-success pb-1\">1. Manual (\"A pelo\")</h6>\n<p class=\"small text-muted\">Añades valores estáticos que tú escribes.</p>\n<pre><code class=\"language-sql\">INSERT INTO Platos (nombre, precio) \nVALUES ('Arepa Nueva', 5.50);</code></pre>\n</div>\n<div class=\"col-md-6\">\n<h6 class=\"text-white border-bottom border-info pb-1\">2. Desde una Consulta</h6>\n<p class=\"small text-muted\">Los datos vienen de un <code>SELECT</code> previo.</p>\n<pre><code class=\"language-sql\">INSERT INTO Clientes_VIP (nombre) \nSELECT nombre FROM Clientes WHERE puntos &gt; 100;</code></pre>\n</div>\n</div>\n<h5 class=\"mt-3 text-info\"><i class=\"fas fa-pencil-alt me-2\"></i>Ejercicios INSERT\n                                (1-4)</h5>\n<div class=\"accordion accordion-flush bg-transparent\" id=\"accordionDML-Ins\">\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-ins-1\" data-bs-toggle=\"collapse\" type=\"button\">1. Nuevo\n                                            Cliente</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Ins\" id=\"ex-ins-1\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Inserta un nuevo cliente llamado \"Pedro\n                                                Picapiedra\" con email \"pedro@roca.com\".<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">INSERT INTO Clientes (nombre, apellido, email) VALUES ('Pedro', 'Picapiedra', 'pedro@roca.com');</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-ins-2\" data-bs-toggle=\"collapse\" type=\"button\">2. Nuevo\n                                            Plato Completo</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Ins\" id=\"ex-ins-2\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Inserta un nuevo plato \"Cachapa con Queso\" a\n                                                8.50, categoría \"Platos Principales\" y disponible.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">INSERT INTO Platos (nombre_plato, precio_venta, categoria, disponible) \nVALUES ('Cachapa con Queso', 8.50, 'Platos Principales', TRUE);</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-ins-3\" data-bs-toggle=\"collapse\" type=\"button\">3.\n                                            Insertar solo obligatorios</button>\n</h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Ins\" id=\"ex-ins-3\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Inserta un cliente solo con Nombre y Apellido\n                                                ('Solo', 'Nombre'), asumiendo que el email acepta NULL.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">INSERT INTO Clientes (nombre, apellido) VALUES ('Solo', 'Nombre');</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-ins-4\" data-bs-toggle=\"collapse\" type=\"button\">4.\n                                            Insertar desde Select</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Ins\" id=\"ex-ins-4\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Copia los clientes con más de 100 puntos a la\n                                                tabla 'Clientes_VIP'.<br/>\n<span class=\"badge bg-secondary mb-2\">Contexto: General</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">INSERT INTO Clientes_VIP (id, nombre) SELECT id, nombre FROM Clientes WHERE puntos &gt; 100;</pre>\n</details>\n</div>\n</div>\n</div>\n</div>\n</article>\n<article class=\"card bg-glass border-0 shadow-sm p-4 mb-4\" id=\"dml-update\">\n<h3 class=\"text-warning\">3.2 UPDATE (Actualizar)</h3>\n<p class=\"text-secondary mb-3\">\n<code>UPDATE</code> modifica datos <strong>ya existentes</strong>. Es\n                                <span class=\"text-danger fw-bold\">CRÍTICO</span> usar siempre <code>WHERE</code>,\n                                de lo contrario, ¡actualizarás TODAS las filas de la tabla con el mismo valor!\n                            </p>\n<pre><code class=\"language-sql\">-- SINTAXIS BÁSICA (¡CUIDADO CON EL WHERE!)\nUPDATE Tabla SET columna = nuevo_valor WHERE condicion;</code></pre>\n<h5 class=\"mt-3 text-info\"><i class=\"fas fa-pencil-alt me-2\"></i>Ejercicios UPDATE\n                                (5-7)</h5>\n<div class=\"accordion accordion-flush bg-transparent\" id=\"accordionDML-Upd\">\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-upd-5\" data-bs-toggle=\"collapse\" type=\"button\">5.\n                                            Corregir Email</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Upd\" id=\"ex-upd-5\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Actualiza el email del cliente con ID 5 a\n                                                'nuevo@email.com'.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">UPDATE Clientes SET email = 'nuevo@email.com' WHERE cliente_id = 5;</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-upd-6\" data-bs-toggle=\"collapse\" type=\"button\">6. Oferta\n                                            General</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Upd\" id=\"ex-upd-6\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Aplica un descuento del 10% a todos los\n                                                platos de la categoría 'Postres'.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">UPDATE Platos SET precio_venta = precio_venta * 0.90 WHERE categoria = 'Postres';</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-upd-7\" data-bs-toggle=\"collapse\" type=\"button\">7. Marcar\n                                            como Agotado</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Upd\" id=\"ex-upd-7\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Marca como NO disponible (FALSE) el plato\n                                                'Pabellón Criollo'.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">UPDATE Platos SET disponible = FALSE WHERE nombre_plato = 'Pabellón Criollo';</pre>\n</details>\n</div>\n</div>\n</div>\n</div>\n</article>\n<article class=\"card bg-glass border-0 shadow-sm p-4 mb-4\" id=\"dml-delete\">\n<h3 class=\"text-danger\">3.3 DELETE (Borrar)</h3>\n<p class=\"text-secondary mb-3\">\n<code>DELETE</code> elimina filas completas de una tabla. Al igual que con el UPDATE,\n                                si olvidas el <code>WHERE</code>, <strong>borrarás todo el contenido</strong> de la\n                                tabla.\n                                No se pueden recuperar los datos eliminados sin un backup.\n                            </p>\n<pre><code class=\"language-sql\">-- SINTAXIS BÁSICA\nDELETE FROM Tabla WHERE condicion;</code></pre>\n<h5 class=\"mt-3 text-info\"><i class=\"fas fa-pencil-alt me-2\"></i>Ejercicios DELETE\n                                (8-10)</h5>\n<div class=\"accordion accordion-flush bg-transparent\" id=\"accordionDML-Del\">\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-del-8\" data-bs-toggle=\"collapse\" type=\"button\">8. Borrar\n                                            Cliente</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Del\" id=\"ex-del-8\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Elimina al cliente con ID 99.<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">DELETE FROM Clientes WHERE cliente_id = 99;</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-del-9\" data-bs-toggle=\"collapse\" type=\"button\">9.\n                                            Limpiar Logs Antiguos</button></h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Del\" id=\"ex-del-9\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Borra todos los logs con fecha anterior al\n                                                '2020-01-01'.<br/>\n<span class=\"badge bg-secondary mb-2\">Contexto: General</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">DELETE FROM Logs WHERE fecha &lt; '2020-01-01';</pre>\n</details>\n</div>\n</div>\n</div>\n<div class=\"accordion-item bg-transparent border-secondary\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed bg-dark text-light bg-opacity-50\" data-bs-target=\"#ex-del-10\" data-bs-toggle=\"collapse\" type=\"button\">10.\n                                            Borrado con Subconsulta</button>\n</h2>\n<div class=\"accordion-collapse collapse\" data-bs-parent=\"#accordionDML-Del\" id=\"ex-del-10\">\n<div class=\"accordion-body text-secondary\">\n<p><strong>Enunciado:</strong> Borra todos los clientes que no tengan\n                                                direccion de email registrada (IS NULL).<br/>\n<span class=\"badge bg-info text-dark mb-2\">Contexto: Arepazo</span>\n</p>\n<details>\n<summary class=\"btn btn-sm btn-outline-light mb-2\">Ver Solución SQL\n                                                </summary>\n<pre class=\"bg-dark p-2 rounded text-success\">DELETE FROM Clientes WHERE email IS NULL;</pre>\n</details>\n</div>\n</div>\n</div>\n</div>\n</article>\n</section><section class=\"\" id=\"dml-advanced-modifications\">\n<h3 class=\"text-white mt-5 border-bottom pb-2\">3.4 Modificaciones Avanzadas</h3>\n<!-- 1. INSERT FROM QUERY WITH JOIN -->\n<article class=\"card bg-glass border-0 shadow-sm p-4 mb-4\" id=\"adv-insert\">\n<h4 class=\"text-success\"><i class=\"fas fa-copy me-2\"></i>3.4.1 INSERT desde SELECT\n                            </h4>\n<p class=\"text-secondary\">\n                                Imagina que quieres regalar un cupón a todos los usuarios que han comprado 'Arepas'.\n                                No necesitas un script de Python. ¡Puedes insertar directamente el resultado de una\n                                consulta compleja!\n                            </p>\n<div class=\"alert alert-success bg-opacity-10 border-success mb-3\">\n<i class=\"fas fa-lightbulb me-2\"></i><strong>Concepto:</strong>\n<code>INSERT INTO ... SELECT ...</code> permite copiar datos de una tabla a otra\n                                basándose en una consulta. Es muy potente para migraciones o tablas de resumen.\n                            </div>\n<div class=\"dml-anim-container h-auto d-block\" id=\"anim-insert\">\n<!-- TARGET (INSERT) -->\n<div class=\"mb-2 d-flex align-items-center gap-2\">\n<span class=\"code-token text-success\">INSERT INTO Cupones</span>\n<span class=\"code-token border border-success px-2\" id=\"ins-cols-target\">(cliente_id, codigo)</span>\n<span class=\"badge bg-success opacity-0 transition-opacity\" id=\"ins-match-badge\">\n<i class=\"fas fa-check me-1\"></i>2 Campos = 2 Campos\n                                    </span>\n</div>\n<!-- SOURCE (SELECT) -->\n<div class=\"d-flex flex-wrap gap-2 align-items-center\">\n<span class=\"code-token\">SELECT DISTINCT</span>\n<span class=\"code-token border border-info px-2\" id=\"ins-cols-source\">c.id,\n                                        'AREPA_LOVER'</span>\n<div class=\"w-100\"></div> <!-- Line break -->\n<span class=\"code-token\">FROM Clientes c</span>\n<span class=\"code-token\">INNER JOIN Pedidos p ON c.id = p.cliente_id</span>\n<span class=\"code-token\">WHERE p.producto = 'Arepa'</span>\n</div>\n</div>\n<div class=\"mt-3 text-end\">\n<button class=\"btn btn-outline-success btn-sm\" onclick=\"playInsertAnim()\">\n<i class=\"fas fa-play me-2\"></i>Ver Animación\n                                </button>\n</div>\n</article>\n<!-- 2. UPDATE WITH JOIN Logic -->\n<article class=\"card bg-glass border-0 shadow-sm p-4 mb-4\" id=\"adv-update\">\n<h4 class=\"text-warning\"><i class=\"fas fa-edit me-2\"></i>3.4.2 UPDATE desde SELECT\n                            </h4>\n<p class=\"text-secondary\">\n                                ¿Calcular una columna compleja? Primero visualízala con un SELECT.\n                                Luego cambia la coma <code>,</code> por un igual <code>=</code> y el SELECT por UPDATE.\n                            </p>\n<div class=\"dml-anim-container d-block\" id=\"anim-update\" style=\"min-height: 180px;\">\n<!-- LINE 1: SELECT / UPDATE -->\n<div class=\"mb-2\">\n<span class=\"code-token text-info\" id=\"upd-verb-select\">SELECT</span>\n<span class=\"code-token text-warning hidden\" id=\"upd-verb-update\">UPDATE Productos p\n                                        SET</span>\n</div>\n<!-- LINE 2: COLUMNS / SET assignment -->\n<div class=\"mb-2 ps-4\">\n<span class=\"code-token\" id=\"upd-col-target\">p.popularidad</span>\n<!-- The Transformation: Comma becomes Equals -->\n<span class=\"code-token fw-bold\" id=\"upd-symbol-comma\">,</span>\n<span class=\"code-token fw-bold text-warning hidden\" id=\"upd-symbol-equals\">=</span>\n<span class=\"code-token\" id=\"upd-col-source\">COUNT(d.id)</span>\n</div>\n<!-- LINE 3: FROM / JOIN -->\n<div class=\"mb-2\">\n<span class=\"code-token\" id=\"upd-from\">FROM Productos p</span>\n<span class=\"code-token\">INNER JOIN DetallesPedido d ON p.id = d.producto_id</span>\n</div>\n<!-- LINE 4: GROUP BY -->\n<div class=\"mb-2\">\n<span class=\"code-token\">GROUP BY p.id</span>\n</div>\n</div>\n<div class=\"mt-3 text-end\">\n<button class=\"btn btn-outline-warning btn-sm\" onclick=\"playUpdateAnim()\">\n<i class=\"fas fa-play me-2\"></i>Ver Animación\n                                </button>\n</div>\n</article>\n<!-- 3. DELETE WITH SUBQUERY -->\n<article class=\"card bg-glass border-0 shadow-sm p-4 mb-4\" id=\"adv-delete\">\n<h4 class=\"text-danger\"><i class=\"fas fa-trash-alt me-2\"></i>3.4.3 DELETE con Subconsulta\n                            </h4>\n<div class=\"alert alert-danger bg-opacity-25 border-danger\">\n<i class=\"fas fa-exclamation-triangle me-2\"></i>\n<strong>¡IMPORTANTE!</strong> La subconsulta dentro del <code>IN (...)</code> debe\n                                devolver\n                                <strong>UNA SOLA COLUMNA</strong> (generalmente el ID). Si devuelves `SELECT *`,\n                                fallará.\n                            </div>\n<p class=\"text-secondary\">Borrar usuarios que no han hecho pedidos en el último año.</p>\n<div class=\"dml-anim-container d-block\" id=\"anim-delete\" style=\"min-height: 150px; position: relative;\">\n<!-- OUTER DELETE -->\n<div class=\"mb-3\" id=\"del-outer\">\n<span class=\"code-token text-danger\">DELETE FROM Usuarios WHERE id IN (</span>\n<span class=\"code-token text-muted\" id=\"del-placeholder\">...</span>\n<span class=\"code-token text-danger\">);</span>\n</div>\n<!-- SUBQUERY (Initially below, then moves up) -->\n<div id=\"del-subquery-container\" style=\"transition: all 1s ease-in-out;\">\n<div class=\"subquery-box d-inline-block text-white border-info bg-dark\" id=\"del-subquery\">\n<span class=\"code-token text-info\">SELECT user_id</span>\n<span class=\"code-token\">FROM Logins</span>\n<span class=\"code-token\">WHERE fecha &lt; '2023-01-01' </span>\n</div>\n</div>\n<!-- RESULT PREVIEW (Hidden) -->\n<div class=\"mt-2 hidden text-end text-muted small\" id=\"del-results\">\n<i class=\"fas fa-arrow-up\"></i> Inyectando IDs: 10, 45, 99...\n                                </div>\n</div>\n<div class=\"mt-3 text-end\">\n<button class=\"btn btn-outline-danger btn-sm\" onclick=\"playDeleteAnim()\">\n<i class=\"fas fa-play me-2\"></i>Ver Integración\n                                </button>\n</div>\n</article>\n<!-- REAL WORLD CASE STUDY -->\n<!-- REAL WORLD CASE STUDY: GDPR / DELETION -->\n<!-- REAL WORLD CASE STUDY: MERGED -->\n<section class=\"mb-5\" id=\"real-world-store\">\n<h3 class=\"text-white border-bottom border-primary pb-2 mb-4\">\n<i class=\"fas fa-store me-2 text-primary\"></i>3.5 Caso Real: Una Tienda\n                            </h3>\n<!-- 3.5.1 GDPR / DELETION -->\n<article class=\"card bg-glass border-0 shadow-sm p-4 mb-4 border-primary\" id=\"adv-gdpr\">\n<h4 class=\"text-white border-bottom border-secondary pb-2 mb-3\">\n<i class=\"fas fa-user-slash me-2 text-warning\"></i>3.5.1 GDPR (Borrado de Clientes)\n                                </h4>\n<p>\n<strong>El Problema:</strong> Un cliente pide la baja. ¿Qué haces con sus Pedidos?\n                                    Tienes 3 estrategias comunes.\n                                </p>\n<ul class=\"nav nav-pills mb-3\" id=\"pills-tab-gdpr\" role=\"tablist\">\n<li class=\"nav-item\" role=\"presentation\">\n<button class=\"nav-link active\" data-bs-target=\"#pills-opt1\" data-bs-toggle=\"pill\" id=\"pills-opt1-tab\" role=\"tab\" type=\"button\">1. Borrado\n                                            Total</button>\n</li>\n<li class=\"nav-item\" role=\"presentation\">\n<button class=\"nav-link\" data-bs-target=\"#pills-opt2\" data-bs-toggle=\"pill\" id=\"pills-opt2-tab\" role=\"tab\" type=\"button\">2. PII\n                                            Anonimizado</button>\n</li>\n<li class=\"nav-item\" role=\"presentation\">\n<button class=\"nav-link\" data-bs-target=\"#pills-opt3\" data-bs-toggle=\"pill\" id=\"pills-opt3-tab\" role=\"tab\" type=\"button\">3. Desvincular\n                                            (NULL)</button>\n</li>\n</ul>\n<div class=\"tab-content\" id=\"pills-tabContent-gdpr\">\n<!-- OPTION 1: CASCADE DELETE -->\n<div class=\"tab-pane fade show active\" id=\"pills-opt1\" role=\"tabpanel\">\n<div class=\"alert alert-danger bg-opacity-10 border-danger\">\n<i class=\"fas fa-biohazard me-2\"></i><strong>Destructivo:</strong>\n                                            Borras al cliente Y TAMBIÉN sus pedidos. Pierdes historial de ventas.\n                                        </div>\n<div class=\"bg-dark p-3 rounded border border-secondary font-monospace text-light\">\n<div><span class=\"text-info\">START TRANSACTION;</span></div>\n<div class=\"text-muted mt-2\">-- 1. Borrar detalles (Un IN con JOIN dentro)\n                                            </div>\n<div>DELETE FROM DetallesPedido WHERE pedido_id IN (</div>\n<div>  SELECT p.id FROM Pedidos p</div>\n<div>  INNER JOIN Clientes c ON p.cliente_id = c.id</div>\n<div>  WHERE c.email = 'juan@gmail.com'</div>\n<div>);</div>\n<div class=\"text-muted mt-2\">-- 2. Borrar pedidos del cliente</div>\n<div>DELETE FROM Pedidos WHERE cliente_id IN (</div>\n<div>  SELECT id FROM Clientes WHERE email = 'juan@gmail.com'\n                                            </div>\n<div>);</div>\n<div class=\"text-muted mt-2\">-- 3. Finalmente, borrar al cliente</div>\n<div>DELETE FROM Clientes WHERE email = 'juan@gmail.com';</div>\n<div><span class=\"text-info\">COMMIT;</span></div>\n</div>\n</div>\n<!-- OPTION 2: OBFUSCATION (Recommended) -->\n<div class=\"tab-pane fade\" id=\"pills-opt2\" role=\"tabpanel\">\n<div class=\"alert alert-success bg-opacity-10 border-success\">\n<i class=\"fas fa-check-circle me-2\"></i><strong>Recomendado (GDPR):</strong>\n                                            Mantienes los datos de ventas pero el cliente se vuelve anónimo.\n                                        </div>\n<div class=\"bg-dark p-3 rounded border border-secondary font-monospace text-light\">\n<div><span class=\"text-warning\">UPDATE</span> Clientes</div>\n<div>SET nombre = <span class=\"text-success\">'Anónimo'</span>,</div>\n<div>    email = CONCAT('borrado_', id, '@anonimo.com'),\n                                            </div>\n<div>    telefono = NULL,</div>\n<div>    direccion = 'Destruido'</div>\n<div>WHERE email = 'juan@gmail.com';</div>\n<div class=\"text-muted mt-2\">-- Resultado: Los pedidos siguen existiendo,\n                                                pero\n                                                son de \"Anónimo\".</div>\n</div>\n</div>\n<!-- OPTION 3: SET NULL -->\n<div class=\"tab-pane fade\" id=\"pills-opt3\" role=\"tabpanel\">\n<div class=\"alert alert-warning bg-opacity-10 border-warning\">\n<i class=\"fas fa-link me-2\"></i><strong>Híbrido:</strong>\n                                            Los pedidos quedan \"huérfanos\" (sin cliente) y borras la ficha.\n                                        </div>\n<div class=\"bg-dark p-3 rounded border border-secondary font-monospace text-light\">\n<div><span class=\"text-info\">START TRANSACTION;</span></div>\n<div class=\"text-muted mt-2\">-- 1. Desvincular pedidos (FK debe permitir\n                                                NULL)\n                                            </div>\n<div>UPDATE Pedidos SET cliente_id = <span class=\"text-warning\">NULL</span>\n</div>\n<div>WHERE cliente_id = (SELECT id FROM Clientes WHERE email =\n                                                'juan@gmail.com');</div>\n<div class=\"text-muted mt-2\">-- 2. Ahora es seguro borrar al cliente</div>\n<div>DELETE FROM Clientes WHERE email = 'juan@gmail.com';</div>\n<div class=\"mt-2\"><span class=\"text-info\">COMMIT;</span></div>\n</div>\n</div>\n</div>\n</article>\n<!-- 3.5.2 E-COMMERCE CHECKOUT -->\n<article class=\"card bg-glass border-0 shadow-sm p-4 mb-4 border-primary\" id=\"adv-case\">\n<h4 class=\"text-primary border-bottom border-secondary pb-2 mb-3\">\n<i class=\"fas fa-shopping-cart me-2\"></i>3.5.2 Un Pedido (Tienda Online)\n                                </h4>\n<p>\n<strong>El Escenario:</strong> Un usuario hace login, añade productos al carrito\n                                    (con\n                                    cantidades) y paga.\n                                    Observa cómo la BB.DD. recupera precios, calcula subtotales y aplica gastos de\n                                    envío.\n                                </p>\n<!-- Animation Container -->\n<div class=\"row g-0 border rounded overflow-hidden mb-4\" style=\"background-color: #0f172a;\">\n<!-- Left: Store Interface -->\n<div class=\"col-md-5 border-end border-secondary p-3\">\n<h6 class=\"text-white border-bottom border-secondary pb-2 mb-3\"><i class=\"fas fa-desktop me-2\"></i>Mi Carrito (Frontend)</h6>\n<!-- User Status -->\n<div class=\"d-flex justify-content-between align-items-center mb-3\">\n<span class=\"badge bg-secondary\" id=\"shop-user-status\">No Logueado</span>\n<small class=\"text-muted\" id=\"shop-cart-id\">Carrito: -</small>\n</div>\n<!-- Action Buttons -->\n<div class=\"d-grid gap-2 mb-3\">\n<button class=\"btn btn-info btn-sm\" id=\"btn-login\" onclick=\"shopAction('LOGIN')\">\n<i class=\"fas fa-sign-in-alt me-2\"></i>1. Login (Ana)\n                                            </button>\n<div class=\"d-flex gap-1\">\n<button class=\"btn btn-outline-light btn-sm w-100\" disabled=\"\" id=\"btn-add-iphone\" onclick=\"shopAction('ADD', 'iPhone 15', 900, 1)\">\n<i class=\"fas fa-mobile-alt me-1\"></i>2. iPhone (Cant: 1)\n                                                </button>\n</div>\n<div class=\"d-flex gap-1\">\n<button class=\"btn btn-outline-light btn-sm w-100\" disabled=\"\" id=\"btn-add-case\" onclick=\"shopAction('ADD', 'Funda', 20, 3)\">\n<i class=\"fas fa-square me-1\"></i>3. Fundas (Cant: 3)\n                                                </button>\n</div>\n<button class=\"btn btn-success btn-sm\" disabled=\"\" id=\"btn-checkout\" onclick=\"shopAction('CHECKOUT')\">\n<i class=\"fas fa-credit-card me-2\"></i>4. Pagar (Checkout)\n                                            </button>\n</div>\n<!-- Virtual Cart Display -->\n<div class=\"bg-white text-dark p-2 rounded font-monospace small\" style=\"min-height: 150px;\">\n<div class=\"text-center fw-bold border-bottom mb-1\">RESUMEN PEDIDO</div>\n<div id=\"shop-cart-items\">\n<!-- Items go here -->\n</div>\n<div class=\"border-top mt-2 pt-1\">\n<div class=\"d-flex justify-content-between\">\n<span>Subtotal:</span>\n<span id=\"shop-subtotal\">0.00€</span>\n</div>\n<div class=\"d-flex justify-content-between text-muted\">\n<span>Envío:</span>\n<span id=\"shop-shipping\">--</span>\n</div>\n<div class=\"d-flex justify-content-between fw-bold fs-6 mt-1\">\n<span>TOTAL:</span>\n<span id=\"shop-total\">0.00€</span>\n</div>\n</div>\n</div>\n</div>\n<!-- Right: Database Log (SQL) -->\n<div class=\"col-md-7 p-3 bg-black font-monospace\">\n<h6 class=\"text-success border-bottom border-secondary pb-2 mb-3\"><i class=\"fas fa-database me-2\"></i>Log de Base de Datos</h6>\n<div class=\"small text-info\" id=\"shop-sql-log\" style=\"height: 350px; overflow-y: auto;\">\n<div class=\"text-muted fst-italic\">Esperando acciones de usuario...</div>\n</div>\n</div>\n</div>\n<!-- Explanation Text -->\n<div class=\"alert alert-info bg-opacity-10 border-info text-light small\">\n<i class=\"fas fa-info-circle me-2\"></i>\n<strong>Puntos Clave:</strong>\n<ul class=\"mb-0 mt-1 ps-3\">\n<li><strong>SELECT antes de INSERT:</strong> Necesitamos saber ID de usuario y\n                                            Precio actual del producto.</li>\n<li><strong>Lógica de Negocio en SQL:</strong> El cálculo del envío se puede\n                                            hacer\n                                            en el `UPDATE` final.</li>\n<li><strong>Transacciones:</strong> Todo el checkout debe ser atómico.</li>\n</ul>\n</div>\n</article>\n</section>\n<!-- SAFETY: TRANSACTIONS & MEMES -->\n<article class=\"card bg-glass border-0 shadow-sm p-4 mb-4 border-danger\" id=\"adv-safety\">\n<h3 class=\"text-white\"><i class=\"fas fa-shield-alt me-2 text-primary\"></i>3.6 Seguridad:\n                                DELETE sin WHERE</h3>\n<div class=\"row align-items-center mb-4\">\n<div class=\"col-md-6\">\n<h5 class=\"text-info\">El Peligro es Real</h5>\n<p class=\"text-secondary small\">\n                                        Ejecutar un <code>DELETE</code> o <code>UPDATE</code> sin filtrar afecta a\n                                        <strong>TODAS</strong> las filas. Si trabajas en producción, esto es despido\n                                        inmediato.\n                                    </p>\n<div class=\"ratio ratio-16x9 rounded overflow-hidden shadow\">\n<iframe allowfullscreen=\"\" src=\"https://www.youtube-nocookie.com/embed/i_cVJgIz_Cs\" title=\"La Cumbia del Delete\"></iframe>\n</div>\n<p class=\"text-center text-muted small mt-2\">🎵 \"La Cumbia del Delete\" - Un clásico\n                                        🎵</p>\n</div>\n<div class=\"col-md-6 text-center\">\n<h5 class=\"text-danger mb-3\">Galería del Terror</h5>\n<!-- Carousel for Memes -->\n<div class=\"carousel slide\" data-bs-ride=\"carousel\" id=\"memeCarousel\">\n<div class=\"carousel-inner rounded shadow border border-secondary\">\n<div class=\"carousel-item active\">\n<img alt=\"Meme Disaster\" class=\"d-block w-100\" src=\"img/meme_delete_where.webp\"/>\n<div class=\"carousel-caption d-none d-md-block bg-dark bg-opacity-75 rounded p-1\">\n<p class=\"mb-0 small\">Cuando ves el \"Rows affected: 15,420\"</p>\n</div>\n</div>\n<div class=\"carousel-item\">\n<img alt=\"Meme Gru Plan\" class=\"d-block w-100\" src=\"img/meme_gru_plan.webp\"/>\n<div class=\"carousel-caption d-none d-md-block bg-dark bg-opacity-75 rounded p-1\">\n<p class=\"mb-0 small\">El Plan Perfecto... con un fallo fatal</p>\n</div>\n</div>\n<!-- User Added Memes -->\n<div class=\"carousel-item\"><img alt=\"Meme User 1\" class=\"d-block w-100\" src=\"img/deletessinwhere/delete01.jpg\"/></div>\n<div class=\"carousel-item\"><img alt=\"Meme User 2\" class=\"d-block w-100\" src=\"img/deletessinwhere/delete02.jpg\"/></div>\n<div class=\"carousel-item\"><img alt=\"Meme User 3\" class=\"d-block w-100\" src=\"img/deletessinwhere/delete03.jpg\"/></div>\n<div class=\"carousel-item\"><img alt=\"Meme User 4\" class=\"d-block w-100\" src=\"img/deletessinwhere/delete04.jpeg\"/></div>\n<div class=\"carousel-item\"><img alt=\"Meme User 5\" class=\"d-block w-100\" src=\"img/deletessinwhere/delete05.jpg\"/></div>\n<div class=\"carousel-item\"><img alt=\"Meme User 6\" class=\"d-block w-100\" src=\"img/deletessinwhere/delete06.jpg\"/></div>\n<div class=\"carousel-item\"><img alt=\"Meme User 7\" class=\"d-block w-100\" src=\"img/deletessinwhere/delete07.jpeg\"/></div>\n<div class=\"carousel-item\"><img alt=\"Meme User 8\" class=\"d-block w-100\" src=\"img/deletessinwhere/delete08.jpeg\"/></div>\n<div class=\"carousel-item\"><img alt=\"Meme User 9\" class=\"d-block w-100\" src=\"img/deletessinwhere/delete09.jpeg\"/></div>\n<div class=\"carousel-item\"><img alt=\"Meme User 10\" class=\"d-block w-100\" src=\"img/deletessinwhere/delete10.jpeg\"/></div>\n<div class=\"carousel-item\"><img alt=\"Meme User 11\" class=\"d-block w-100\" src=\"img/deletessinwhere/delete11.jpeg\"/></div>\n<div class=\"carousel-item\"><img alt=\"Meme User 12\" class=\"d-block w-100\" src=\"img/deletessinwhere/delete12.jpeg\"/></div>\n<div class=\"carousel-item\"><img alt=\"Meme User 13\" class=\"d-block w-100\" src=\"img/deletessinwhere/delete13.jpeg\"/></div>\n<div class=\"carousel-item\"><img alt=\"Meme User 14\" class=\"d-block w-100\" src=\"img/deletessinwhere/delete14.jpeg\"/></div>\n</div>\n<button class=\"carousel-control-prev\" data-bs-slide=\"prev\" data-bs-target=\"#memeCarousel\" style=\"filter: invert(1);\" type=\"button\">\n<span aria-hidden=\"true\" class=\"carousel-control-prev-icon\"></span>\n<span class=\"visually-hidden\">Anterior</span>\n</button>\n<button class=\"carousel-control-next\" data-bs-slide=\"next\" data-bs-target=\"#memeCarousel\" style=\"filter: invert(1);\" type=\"button\">\n<span aria-hidden=\"true\" class=\"carousel-control-next-icon\"></span>\n<span class=\"visually-hidden\">Siguiente</span>\n</button>\n</div>\n</div>\n</div>\n<!-- 3.6.1 Transactions -->\n<div class=\"mt-5 border-top border-secondary pt-4\" id=\"adv-transactions\">\n<h4 class=\"text-warning\"><i class=\"fas fa-undo-alt me-2\"></i>3.6.1 Transacciones: El\n                                    \"Ctrl+Z\" de la Base de Datos</h4>\n<p class=\"text-secondary\">\n                                    ¿Alguna vez has enviado un mensaje de WhatsApp a la persona equivocada y has deseado\n                                    borrarlo antes de que lo lea?\n                                    Bueno, en SQL, <strong>SI PUEDES</strong> (si eres listo).\n                                </p>\n<div class=\"row align-items-center\">\n<div class=\"col-md-7\">\n<div class=\"alert alert-warning bg-opacity-10 border-warning\">\n<h5 class=\"alert-heading text-warning\"><i class=\"fas fa-exclamation-triangle me-2\"></i>Regla de Oro para\n                                                Sobrevivir</h5>\n<p class=\"mb-0\">\n                                                Antes de ejecutar cualquier <code>DELETE</code> o <code>UPDATE</code>\n                                                masivo, ¡abre una transacción!\n                                                Es tu red de seguridad. Si metes la pata (y lo harás), puedes hacer\n                                                <strong>ROLLBACK</strong> y volver al pasado como si nada hubiera\n                                                ocurrido.\n                                            </p>\n</div>\n<div class=\"bg-dark p-3 rounded border border-secondary font-monospace text-light\">\n<span class=\"text-info\">-- 1. Empieza la magia (Modo Seguro ON)</span><br/>\n<span class=\"text-primary fw-bold\">BEGIN;</span><br/><br/>\n<span class=\"text-info\">-- 2. Ejecuta tu sentencia peligrosa</span><br/>\n<span class=\"text-light\">DELETE FROM Usuarios;</span> <span class=\"text-danger fw-bold\">-- ¡UPS! ¡OLVIDÉ EL WHERE! 😱</span><br/><br/>\n<span class=\"text-info\">-- 3. ¿El resultado es un desastre?</span><br/>\n<span class=\"text-warning fw-bold\">ROLLBACK;</span> <span class=\"text-success\">-- ¡Fiú! Todo vuelve a estar bien.\n                                                😌</span><br/><br/>\n<span class=\"text-info\">-- 4. ¿Todo correcto? (Solo entonces...)</span><br/>\n<span class=\"text-success fw-bold\">COMMIT;</span> <span class=\"text-muted\">-- Guardar cambios para siempre.</span>\n</div>\n</div>\n<div class=\"col-md-5 text-center\">\n<img alt=\"Meme Transaction Rollback\" class=\"img-fluid rounded shadow-lg border border-warning\" src=\"img/rollback_lifesaver_meme.png\"/>\n<p class=\"small text-muted mt-2\"><em>Tu ángel de la guarda se llama\n                                                ROLLBACK</em></p>\n</div>\n</div>\n</div>\n<!-- Tattoos Image -->\n<div class=\"text-center mt-5\">\n<h5 class=\"text-white mb-3\">Filosofía de Vida (Tatuajes Obligatorios)</h5>\n<div class=\"d-inline-block position-relative\">\n<img alt=\"Tatuajes SQL Safety\" class=\"img-fluid rounded shadow-lg border border-danger\" src=\"img/safety_tattoos_meme_v2.png\" style=\"max-height: 400px;\"/>\n<div class=\"position-absolute top-50 start-0 translate-middle-y bg-dark bg-opacity-75 p-2 rounded text-white small fw-bold ms-2\" style=\"max-width: 150px;\">\n                                        NI UN DELETE/UPDATE SIN WHERE\n                                    </div>\n<div class=\"position-absolute top-50 end-0 translate-middle-y bg-dark bg-opacity-75 p-2 rounded text-white small fw-bold me-2\" style=\"max-width: 150px;\">\n                                        NI UN DELETE/UPDATE SIN BEGIN ROLLBACK\n                                    </div>\n</div>\n</div>\n<div class=\"alert alert-info border-info bg-opacity-10 mt-4\">\n<i class=\"fas fa-life-ring me-2\"></i><strong>Consejo Pro:</strong>\n                                Siempre escribe el <code>SELECT</code> antes que el <code>DELETE</code> para verificar\n                                qué vas a borrar.\n                                <br/>\n<code>SELECT * FROM Usuarios WHERE id = 5;</code> -&gt; ¿Es el correcto? -&gt;\n                                <code>DELETE ...</code>\n</div>\n</article>\n</section><section class=\"mb-5\" id=\"real-world-store\">\n<h3 class=\"text-white border-bottom border-primary pb-2 mb-4\">\n<i class=\"fas fa-store me-2 text-primary\"></i>3.5 Caso Real: Una Tienda\n                            </h3>\n<!-- 3.5.1 GDPR / DELETION -->\n<article class=\"card bg-glass border-0 shadow-sm p-4 mb-4 border-primary\" id=\"adv-gdpr\">\n<h4 class=\"text-white border-bottom border-secondary pb-2 mb-3\">\n<i class=\"fas fa-user-slash me-2 text-warning\"></i>3.5.1 GDPR (Borrado de Clientes)\n                                </h4>\n<p>\n<strong>El Problema:</strong> Un cliente pide la baja. ¿Qué haces con sus Pedidos?\n                                    Tienes 3 estrategias comunes.\n                                </p>\n<ul class=\"nav nav-pills mb-3\" id=\"pills-tab-gdpr\" role=\"tablist\">\n<li class=\"nav-item\" role=\"presentation\">\n<button class=\"nav-link active\" data-bs-target=\"#pills-opt1\" data-bs-toggle=\"pill\" id=\"pills-opt1-tab\" role=\"tab\" type=\"button\">1. Borrado\n                                            Total</button>\n</li>\n<li class=\"nav-item\" role=\"presentation\">\n<button class=\"nav-link\" data-bs-target=\"#pills-opt2\" data-bs-toggle=\"pill\" id=\"pills-opt2-tab\" role=\"tab\" type=\"button\">2. PII\n                                            Anonimizado</button>\n</li>\n<li class=\"nav-item\" role=\"presentation\">\n<button class=\"nav-link\" data-bs-target=\"#pills-opt3\" data-bs-toggle=\"pill\" id=\"pills-opt3-tab\" role=\"tab\" type=\"button\">3. Desvincular\n                                            (NULL)</button>\n</li>\n</ul>\n<div class=\"tab-content\" id=\"pills-tabContent-gdpr\">\n<!-- OPTION 1: CASCADE DELETE -->\n<div class=\"tab-pane fade show active\" id=\"pills-opt1\" role=\"tabpanel\">\n<div class=\"alert alert-danger bg-opacity-10 border-danger\">\n<i class=\"fas fa-biohazard me-2\"></i><strong>Destructivo:</strong>\n                                            Borras al cliente Y TAMBIÉN sus pedidos. Pierdes historial de ventas.\n                                        </div>\n<div class=\"bg-dark p-3 rounded border border-secondary font-monospace text-light\">\n<div><span class=\"text-info\">START TRANSACTION;</span></div>\n<div class=\"text-muted mt-2\">-- 1. Borrar detalles (Un IN con JOIN dentro)\n                                            </div>\n<div>DELETE FROM DetallesPedido WHERE pedido_id IN (</div>\n<div>  SELECT p.id FROM Pedidos p</div>\n<div>  INNER JOIN Clientes c ON p.cliente_id = c.id</div>\n<div>  WHERE c.email = 'juan@gmail.com'</div>\n<div>);</div>\n<div class=\"text-muted mt-2\">-- 2. Borrar pedidos del cliente</div>\n<div>DELETE FROM Pedidos WHERE cliente_id IN (</div>\n<div>  SELECT id FROM Clientes WHERE email = 'juan@gmail.com'\n                                            </div>\n<div>);</div>\n<div class=\"text-muted mt-2\">-- 3. Finalmente, borrar al cliente</div>\n<div>DELETE FROM Clientes WHERE email = 'juan@gmail.com';</div>\n<div><span class=\"text-info\">COMMIT;</span></div>\n</div>\n</div>\n<!-- OPTION 2: OBFUSCATION (Recommended) -->\n<div class=\"tab-pane fade\" id=\"pills-opt2\" role=\"tabpanel\">\n<div class=\"alert alert-success bg-opacity-10 border-success\">\n<i class=\"fas fa-check-circle me-2\"></i><strong>Recomendado (GDPR):</strong>\n                                            Mantienes los datos de ventas pero el cliente se vuelve anónimo.\n                                        </div>\n<div class=\"bg-dark p-3 rounded border border-secondary font-monospace text-light\">\n<div><span class=\"text-warning\">UPDATE</span> Clientes</div>\n<div>SET nombre = <span class=\"text-success\">'Anónimo'</span>,</div>\n<div>    email = CONCAT('borrado_', id, '@anonimo.com'),\n                                            </div>\n<div>    telefono = NULL,</div>\n<div>    direccion = 'Destruido'</div>\n<div>WHERE email = 'juan@gmail.com';</div>\n<div class=\"text-muted mt-2\">-- Resultado: Los pedidos siguen existiendo,\n                                                pero\n                                                son de \"Anónimo\".</div>\n</div>\n</div>\n<!-- OPTION 3: SET NULL -->\n<div class=\"tab-pane fade\" id=\"pills-opt3\" role=\"tabpanel\">\n<div class=\"alert alert-warning bg-opacity-10 border-warning\">\n<i class=\"fas fa-link me-2\"></i><strong>Híbrido:</strong>\n                                            Los pedidos quedan \"huérfanos\" (sin cliente) y borras la ficha.\n                                        </div>\n<div class=\"bg-dark p-3 rounded border border-secondary font-monospace text-light\">\n<div><span class=\"text-info\">START TRANSACTION;</span></div>\n<div class=\"text-muted mt-2\">-- 1. Desvincular pedidos (FK debe permitir\n                                                NULL)\n                                            </div>\n<div>UPDATE Pedidos SET cliente_id = <span class=\"text-warning\">NULL</span>\n</div>\n<div>WHERE cliente_id = (SELECT id FROM Clientes WHERE email =\n                                                'juan@gmail.com');</div>\n<div class=\"text-muted mt-2\">-- 2. Ahora es seguro borrar al cliente</div>\n<div>DELETE FROM Clientes WHERE email = 'juan@gmail.com';</div>\n<div class=\"mt-2\"><span class=\"text-info\">COMMIT;</span></div>\n</div>\n</div>\n</div>\n</article>\n<!-- 3.5.2 E-COMMERCE CHECKOUT -->\n<article class=\"card bg-glass border-0 shadow-sm p-4 mb-4 border-primary\" id=\"adv-case\">\n<h4 class=\"text-primary border-bottom border-secondary pb-2 mb-3\">\n<i class=\"fas fa-shopping-cart me-2\"></i>3.5.2 Un Pedido (Tienda Online)\n                                </h4>\n<p>\n<strong>El Escenario:</strong> Un usuario hace login, añade productos al carrito\n                                    (con\n                                    cantidades) y paga.\n                                    Observa cómo la BB.DD. recupera precios, calcula subtotales y aplica gastos de\n                                    envío.\n                                </p>\n<!-- Animation Container -->\n<div class=\"row g-0 border rounded overflow-hidden mb-4\" style=\"background-color: #0f172a;\">\n<!-- Left: Store Interface -->\n<div class=\"col-md-5 border-end border-secondary p-3\">\n<h6 class=\"text-white border-bottom border-secondary pb-2 mb-3\"><i class=\"fas fa-desktop me-2\"></i>Mi Carrito (Frontend)</h6>\n<!-- User Status -->\n<div class=\"d-flex justify-content-between align-items-center mb-3\">\n<span class=\"badge bg-secondary\" id=\"shop-user-status\">No Logueado</span>\n<small class=\"text-muted\" id=\"shop-cart-id\">Carrito: -</small>\n</div>\n<!-- Action Buttons -->\n<div class=\"d-grid gap-2 mb-3\">\n<button class=\"btn btn-info btn-sm\" id=\"btn-login\" onclick=\"shopAction('LOGIN')\">\n<i class=\"fas fa-sign-in-alt me-2\"></i>1. Login (Ana)\n                                            </button>\n<div class=\"d-flex gap-1\">\n<button class=\"btn btn-outline-light btn-sm w-100\" disabled=\"\" id=\"btn-add-iphone\" onclick=\"shopAction('ADD', 'iPhone 15', 900, 1)\">\n<i class=\"fas fa-mobile-alt me-1\"></i>2. iPhone (Cant: 1)\n                                                </button>\n</div>\n<div class=\"d-flex gap-1\">\n<button class=\"btn btn-outline-light btn-sm w-100\" disabled=\"\" id=\"btn-add-case\" onclick=\"shopAction('ADD', 'Funda', 20, 3)\">\n<i class=\"fas fa-square me-1\"></i>3. Fundas (Cant: 3)\n                                                </button>\n</div>\n<button class=\"btn btn-success btn-sm\" disabled=\"\" id=\"btn-checkout\" onclick=\"shopAction('CHECKOUT')\">\n<i class=\"fas fa-credit-card me-2\"></i>4. Pagar (Checkout)\n                                            </button>\n</div>\n<!-- Virtual Cart Display -->\n<div class=\"bg-white text-dark p-2 rounded font-monospace small\" style=\"min-height: 150px;\">\n<div class=\"text-center fw-bold border-bottom mb-1\">RESUMEN PEDIDO</div>\n<div id=\"shop-cart-items\">\n<!-- Items go here -->\n</div>\n<div class=\"border-top mt-2 pt-1\">\n<div class=\"d-flex justify-content-between\">\n<span>Subtotal:</span>\n<span id=\"shop-subtotal\">0.00€</span>\n</div>\n<div class=\"d-flex justify-content-between text-muted\">\n<span>Envío:</span>\n<span id=\"shop-shipping\">--</span>\n</div>\n<div class=\"d-flex justify-content-between fw-bold fs-6 mt-1\">\n<span>TOTAL:</span>\n<span id=\"shop-total\">0.00€</span>\n</div>\n</div>\n</div>\n</div>\n<!-- Right: Database Log (SQL) -->\n<div class=\"col-md-7 p-3 bg-black font-monospace\">\n<h6 class=\"text-success border-bottom border-secondary pb-2 mb-3\"><i class=\"fas fa-database me-2\"></i>Log de Base de Datos</h6>\n<div class=\"small text-info\" id=\"shop-sql-log\" style=\"height: 350px; overflow-y: auto;\">\n<div class=\"text-muted fst-italic\">Esperando acciones de usuario...</div>\n</div>\n</div>\n</div>\n<!-- Explanation Text -->\n<div class=\"alert alert-info bg-opacity-10 border-info text-light small\">\n<i class=\"fas fa-info-circle me-2\"></i>\n<strong>Puntos Clave:</strong>\n<ul class=\"mb-0 mt-1 ps-3\">\n<li><strong>SELECT antes de INSERT:</strong> Necesitamos saber ID de usuario y\n                                            Precio actual del producto.</li>\n<li><strong>Lógica de Negocio en SQL:</strong> El cálculo del envío se puede\n                                            hacer\n                                            en el `UPDATE` final.</li>\n<li><strong>Transacciones:</strong> Todo el checkout debe ser atómico.</li>\n</ul>\n</div>\n</article>\n</section>"
};
export default TEORIA;
